# Chapter 21 Uniform electric fields: 21.1 to 21.4. (Chapter 22 is out of scope.)
QE, ME, MP, MA = 1.60e-19, 9.11e-31, 1.67e-27, 6.64e-27

# ═════════════════════════ 21.1 Attraction and repulsion (16/19/9) ═════════════════════════
lesson('21.1')
M('E', 1, 'A polythene rod is rubbed with a woollen cloth and becomes negatively charged. What has happened?', 'Electrons have moved from the cloth to the rod', ['Protons have moved from the rod to the cloth', 'Electrons have been created on the rod', 'Positive charge has moved from the cloth to the rod'], 'Friction transfers electrons; protons are fixed in the nuclei and charge is never created.')
M('E', 1, 'When an insulator is charged by friction, which particles are transferred?', 'Electrons', ['Protons', 'Neutrons', 'Whole atoms'], 'Only the outer electrons are loosely held enough to be rubbed off.')
N('E', 2, 'A plastic comb gains a charge of −4.8 × 10⁻⁸ C when it is pulled through dry hair. How many electrons has it gained?' + take('e'), 4.8e-8 / QE, None,
  f'N = Q/e = 4.8 × 10⁻⁸ ÷ 1.60 × 10⁻¹⁹ = {sf(4.8e-8 / QE)}', ['C1: N = Q/e'], aq='N')
N('E', 2, 'A balloon rubbed on a jumper gains a charge of +3.2 nC. How many electrons have been removed from it?' + take('e'), 3.2e-9 / QE, None,
  f'N = Q/e = 3.2 × 10⁻⁹ ÷ 1.60 × 10⁻¹⁹ = {sf(3.2e-9 / QE)}', ['C1: nC → C and N = Q/e'], sig=2, aq='N')
M('E', 1, 'A negatively charged balloon sticks to an uncharged wall. Why?', 'Electrons in the wall are repelled, leaving the nearby surface slightly positive, which attracts the balloon', ['The wall becomes negatively charged and attracts the balloon', 'Gravity pulls the balloon onto the wall', 'Air pressure pushes the balloon onto the wall'], 'The balloon induces a separation of charge; the opposite charge is closer, so attraction wins.')
M('E', 1, 'Which unit is equivalent to the coulomb?', 'A s', ['A s⁻¹', 'J V', 'W s'], 'Q = It, so 1 C = 1 A × 1 s.')
M('E', 1, 'Which of these values could NOT be the charge on an object?', '2.4 × 10⁻¹⁹ C', ['3.2 × 10⁻¹⁹ C', '4.8 × 10⁻¹⁹ C', '1.6 × 10⁻¹⁸ C'], 'Charge is quantised in multiples of e = 1.6 × 10⁻¹⁹ C; 2.4 × 10⁻¹⁹ C is 1.5e.')
N('E', 2, 'Two identical metal spheres carry charges of +6.0 nC and −2.0 nC. They are touched together and then separated. Calculate the charge on each sphere.', 2.0, 'nC',
  'Total charge = 6.0 + (−2.0) = 4.0 nC, shared equally: each = 4.0 ÷ 2 = 2.0 nC', ['C1: charge conserved and shared equally'], sig=2, aq='Q')
M('E', 1, 'Why is a metal a good electrical conductor?', 'It contains many free electrons that can move through it', ['Its protons can move freely', 'It has no electrons', 'Its atoms are very small'], 'The delocalised electrons in a metal move easily when a force acts on them.')
M('E', 1, 'A positively charged metal sphere on an insulating stand is connected to earth by a wire. What happens?', 'Electrons flow from the earth to the sphere until it is neutral', ['Protons flow from the sphere to the earth', 'Electrons flow from the sphere to the earth', 'Nothing, because the earth is neutral'], 'The sphere lacks electrons; electrons flow up from earth to neutralise it.')
N('E', 2, 'A spark transfers 5.0 µC of charge in 2.0 µs. Calculate the average current in the spark.', 5.0e-6 / 2.0e-6, 'A',
  'I = Q/t = 5.0 × 10⁻⁶ ÷ 2.0 × 10⁻⁶ = 2.5 A', ['C1: I = Q/t'], sig=2, aq='I')
M('E', 1, 'What does the principle of conservation of charge state?', 'The total charge of an isolated system stays constant', ['Charge can be created by friction', 'Positive charge is always conserved but negative charge is not', 'Charge is always shared equally between objects'], 'Rubbing only moves charge: the gain on one object equals the loss on the other.')
N('E', 1, 'How many electrons together have a total charge of −1.0 C?' + take('e'), 1.0 / QE, None,
  f'N = 1.0 ÷ 1.60 × 10⁻¹⁹ = {sf(1 / QE)}', [], aq='N')
M('E', 1, 'A charged comb picks up small pieces of uncharged paper. Why are the pieces attracted?', 'Charge is induced in the paper, with opposite charge nearer the comb', ['The paper becomes charged with the same sign as the comb', 'The comb is magnetic', 'The paper is pulled by gravity towards the comb'], 'The nearer induced charge is attracted more strongly than the further like charge is repelled.')
M('E', 1, 'A negatively charged rod is brought near a suspended light ball and the ball is repelled. What can be concluded?', 'The ball is negatively charged', ['The ball is positively charged', 'The ball is uncharged', 'The ball is a conductor'], 'Attraction could mean an uncharged ball, but only like charges repel, so repulsion is a reliable test.')
N('E', 2, 'A lightning flash transfers 20 C of charge to the ground in 0.50 ms. Calculate the average current.', 20 / 0.50e-3, 'A',
  'I = Q/t = 20 ÷ 0.50 × 10⁻³ = 4.0 × 10⁴ A', ['C1: I = Q/t with t in s'], sig=2, aq='I')
# medium
N('M', 3, 'The belt of a Van de Graaff generator carries charge to the dome at a steady rate of 3.0 µA. The dome starts uncharged. Calculate the time taken for the charge on the dome to reach 15 µC.', 15e-6 / 3.0e-6, 's',
  't = Q/I = 15 × 10⁻⁶ ÷ 3.0 × 10⁻⁶ = 5.0 s', ['C1: current = rate of flow of charge', 'C1: t = Q/I'], sig=2, aq='t')
M('M', 3, 'A neutral metal sphere is charged by induction using a positively charged rod: the rod is held near the sphere, the sphere is earthed, the earth connection is removed and then the rod is removed. What is the final charge on the sphere?', 'Negative', ['Positive', 'Zero', 'Positive on one side and negative on the other'], 'With the rod near, electrons flow up from earth; breaking the earth before removing the rod traps them, leaving a net negative charge.', ['C1: electrons flow from earth', 'C1: trapped when earth removed first'])
N('M', 3, 'Three identical metal spheres A, B and C are on insulating stands. A carries +9.0 nC and B and C are uncharged. A is touched to B and separated, then A is touched to C and separated. Calculate the final charge on A.', 9.0 / 4, 'nC',
  'After touching B: A = 9.0 ÷ 2 = 4.5 nC. After touching C: A = 4.5 ÷ 2 = 2.25 nC', ['C1: charge shared equally each time', 'C1: two halvings'], aq='Q_A')
M('M', 3, 'A gold-leaf electroscope is negatively charged so its leaf is raised. A negatively charged rod is brought near its cap without touching. What happens to the leaf?', 'It rises further', ['It falls', 'It stays where it is', 'It falls and then rises again'], 'The rod repels more electrons down into the stem and leaf, increasing the repulsion.', ['C1: electrons pushed down to leaf', 'C1: more like charge, more repulsion'])
N('M', 3, 'Calculate the total charge of all the electrons in 1.0 g of hydrogen atoms (molar mass 1.0 g mol⁻¹, one electron per atom).' + take('NA', 'e'), 6.02e23 * QE, 'C',
  f'1.0 g is 1.0 mol, so N = 6.02 × 10²³ electrons. Q = 6.02 × 10²³ × 1.60 × 10⁻¹⁹ = {sf(6.02e23 * QE)} C', ['C1: one mole of electrons', 'C1: Q = Ne'], aq='Q')
N('M', 3, 'In a photocopier, a toner particle carries a charge of −2.4 × 10⁻¹⁵ C. How many excess electrons does it carry?' + take('e'), 2.4e-15 / QE, None,
  f'N = Q/e = 2.4 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁹ = {sf(2.4e-15 / QE)}', ['C1: N = Q/e', 'C1: substitution'], sig=2, aq='N')
M('M', 3, 'A charged plastic rod is touched at one end by a finger, but the rest of the rod stays charged. A charged metal rod on an insulating stand loses all its charge when touched. Why the difference?', 'Charge cannot move through the plastic, so only the touched spot is discharged; in the metal, charge flows freely to the finger', ['Plastic holds charge more strongly because it is heavier', 'Metal has no electrons', 'The finger is a better insulator than plastic'], 'In an insulator electrons are bound to atoms; in a conductor free electrons let the whole object discharge.', ['C1: insulator: charges cannot move', 'C1: conductor: charges flow away'])
N('M', 3, 'An electrostatic paint sprayer gives each paint droplet a charge of −1.6 × 10⁻¹⁴ C. The sprayer delivers a current of 50 µA. Calculate the number of droplets sprayed per second.', 50e-6 / 1.6e-14, 's⁻¹',
  f'Droplets per second = I ÷ q = 50 × 10⁻⁶ ÷ 1.6 × 10⁻¹⁴ = {sf(50e-6 / 1.6e-14)} s⁻¹', ['C1: I = charge per second', 'C1: ÷ charge per droplet'], aq='rate')
M('M', 3, 'An uncharged metal sphere hanging on a thread is attracted towards a positively charged rod. Which explanation is correct?', 'Free electrons move to the near side; attraction of this nearer negative charge exceeds repulsion of the further positive charge', ['The sphere becomes positively charged by the rod', 'The rod transfers electrons to the sphere through the air', 'Uncharged objects are always attracted by gravity to charged ones'], 'Net charge stays zero, but the separated charges are at different distances, and force decreases with distance.', ['C1: electrons move to near side', 'C1: nearer charge gives the larger force'])
N('M', 4, 'A person walking across a nylon carpet becomes charged to −0.50 µC. When they touch a metal door handle, they discharge completely in 1.0 µs. (a) Calculate the number of electrons that flow. (b) Calculate the average current. Give only the answer to (b).' + take('e'), 0.50e-6 / 1.0e-6, 'A',
  f'(a) N = 0.50 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = {sf(0.5e-6 / QE)}. (b) I = Q/t = 0.50 × 10⁻⁶ ÷ 1.0 × 10⁻⁶ = 0.50 A', ['C1: N = Q/e', 'C1: µC and µs converted', 'C1: I = Q/t'], sig=2, aq='I')
M('M', 3, 'Why does a road tanker carrying fuel have a conducting strap connecting its body to the ground?', 'Friction of the flowing fuel can charge the tanker, and the strap lets charge flow to earth before a spark can ignite the fuel', ['To stop the tanker being struck by lightning', 'To keep the fuel cool', 'To make the tanker more stable'], 'Charge builds up by friction; earthing prevents a large potential difference and sparking.', ['C1: charge builds up by friction', 'C1: earthing prevents sparks'])
N('M', 3, 'Two identical metal spheres carry +8.0 nC and −2.0 nC. They are touched together and separated. Calculate the number of electrons that move from one sphere to the other.' + take('e'), 5.0e-9 / QE, None,
  f'Each ends with (8.0 − 2.0) ÷ 2 = 3.0 nC. The first sphere changes from +8.0 nC to +3.0 nC, so it gains 5.0 nC of electrons: N = 5.0 × 10⁻⁹ ÷ 1.60 × 10⁻¹⁹ = {sf(5e-9 / QE)}', ['C1: final charge 3.0 nC each', 'C1: change of 5.0 nC'], aq='N')
M('M', 3, 'An object has a charge of −3.2 µC. Which statement is correct?', 'It has 2.0 × 10¹³ more electrons than protons', ['It has 2.0 × 10¹³ electrons in total', 'It has 2.0 × 10¹³ fewer electrons than protons', 'It has 3.2 × 10⁶ more electrons than protons'], 'Excess = 3.2 × 10⁻⁶ ÷ 1.6 × 10⁻¹⁹ = 2.0 × 10¹³; a negative charge means extra electrons.', ['C1: N = Q/e', 'C1: negative means excess electrons'])
N('M', 3, 'An electron beam in a vacuum tube carries a current of 2.0 mA. Calculate the number of electrons passing a point each second.' + take('e'), 2.0e-3 / QE, 's⁻¹',
  f'N per second = I/e = 2.0 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = {sf(2e-3 / QE)} s⁻¹', ['C1: I = Ne/t', 'C1: substitution'], aq='rate')
M('M', 4, 'After a polythene rod is rubbed with a cloth, the rod has a charge of −40 nC. Assuming no charge is lost to the surroundings, what is the charge on the cloth?', '+40 nC', ['0', '−40 nC', '+80 nC'], 'Charge is conserved: the electrons gained by the rod came from the cloth, so the cloth has +40 nC.', ['C1: charge conserved', 'C1: electrons transferred from cloth', 'C1: equal and opposite'])
N('M', 3, 'A neutral metal sphere loses 5.0 × 10¹² electrons. Calculate its charge in µC.' + take('e'), 5.0e12 * QE * 1e6, 'µC',
  f'Q = Ne = 5.0 × 10¹² × 1.60 × 10⁻¹⁹ = {sf(5e12 * QE)} C. In µC: {sf(5e12 * QE)} × 10⁶ = +0.80. It is positive because electrons were lost.', ['C1: Q = Ne', 'C1: sign and unit'], sig=2, sign=True, aq='Q')
M('M', 3, 'A charged balloon stuck to a wall eventually falls off. What is the most likely reason?', 'Its charge slowly leaks away to the air and the wall, especially when the air is damp', ['Its charge increases until it is repelled', 'The wall becomes charged with the same sign immediately', 'Gravity increases with time'], 'Moist air and surface films conduct slightly, so the charge, and the induced attraction, decrease.', ['C1: charge leaks away', 'C1: attraction decreases'])
N('M', 3, 'A rod gains a charge of −5.0 µC by friction. Calculate the increase in its mass due to the extra electrons, in units of 10⁻¹⁷ kg.' + take('e', 'me'), 5.0e-6 / QE * ME, '10⁻¹⁷ kg',
  f'N = 5.0 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = {sf(5e-6 / QE)}. Δm = {sf(5e-6 / QE, 4)} × 9.11 × 10⁻³¹ = {sf(5e-6 / QE * ME)} kg', ['C1: N = Q/e', 'C1: Δm = N × mₑ'], aq='Δm')
M('M', 3, 'Two touching, uncharged metal spheres A and B stand on insulating bases. A positively charged rod is held near A. The spheres are pulled apart and then the rod is removed. What are the charges on A and B?', 'A is negative and B is positive, with equal magnitudes', ['A is positive and B is negative', 'Both are positive', 'Both remain uncharged'], 'Electrons are attracted towards the rod into A; separating the spheres traps this distribution. Total charge stays zero.', ['C1: electrons move to A', 'C1: equal and opposite, total zero'])
# hard
N('H', 6, 'Four identical metal spheres A, B, C and D are on insulating stands. A carries +16 nC, B carries −4.0 nC, and C and D are uncharged. In turn: A touches B; A touches C; C touches D. The spheres are separated after each contact. (a) Calculate the charge on A after it touches B. (b) Calculate the charges on A and on C after they touch. (c) Calculate the final charge on C. (d) Show that the total charge at the end equals the total at the start. Give only the answer to (c).', 1.5, 'nC',
  '(a) A and B share (16 − 4.0) = 12 nC: each 12 ÷ 2 = 6.0 nC. (b) A and C share 6.0 nC: each 6.0 ÷ 2 = 3.0 nC. (c) C and D share 3.0 nC: each 3.0 ÷ 2 = 1.5 nC. (d) Final total = 3.0 + 6.0 + 1.5 + 1.5 = 12 nC, the same as 16 − 4.0 at the start.',
  ['C1: equal sharing for identical spheres', 'C1: A after B = 6.0 nC', 'C1: A and C = 3.0 nC', 'B1: total 12 nC conserved', 'M1: signs combined correctly at the first contact'], sig=2, aq='Q_C')
N('H', 5, 'The base of a thundercloud carries −30 C. In one lightning flash lasting 0.20 ms, 75 % of this charge flows to the ground. (a) Calculate the charge transferred. (b) Calculate the average current in the flash. (c) Calculate the number of electrons transferred. Give only the answer to (b).' + take('e'), 0.75 * 30 / 0.20e-3, 'A',
  f'(a) Q = 0.75 × 30 = 22.5 C. (b) I = Q/t = 22.5 ÷ 0.20 × 10⁻³ = {sf(22.5 / 0.2e-3)} A. (c) N = 22.5 ÷ 1.60 × 10⁻¹⁹ = {sf(22.5 / QE)}',
  ['C1: 75 % of 30 C', 'C1: I = Q/t', 'C1: t in s', 'C1: N = Q/e'], aq='I')
N('H', 6, 'An electrostatic precipitator in a power-station chimney gives each smoke particle a charge of 5.0 × 10⁴ electrons. The charged particles are then attracted to earthed collecting plates. The precipitator removes 2.0 × 10¹⁰ particles each second. (a) Calculate the charge on one particle. (b) Calculate the current carried to the collecting plates, in mA. (c) Explain why the particles are attracted to the earthed plates even though the plates are uncharged at first. Give only the answer to (b).' + take('e'), 5.0e4 * QE * 2.0e10 * 1000, 'mA',
  f'(a) q = 5.0 × 10⁴ × 1.60 × 10⁻¹⁹ = {sf(5e4 * QE)} C. (b) I = 2.0 × 10¹⁰ × {sf(5e4 * QE)} = {sf(2e10 * 5e4 * QE)} A. In mA: {sf(2e10 * 5e4 * QE, 4)} × 1000 = {sf(2e10 * 5e4 * QE * 1000)}. (c) The charged particles induce opposite charge on the near surface of the earthed plates, and electrons can flow to or from earth, so there is always attraction.',
  ['C1: q = Ne', 'C1: I = rate × q', 'C1: conversion to mA', 'B1: induced opposite charge', 'B1: earth supplies or removes electrons'], aq='I')
N('H', 5, 'A balloon is rubbed on a person\'s hair and gains a charge of −0.40 µC. (a) Calculate the number of electrons transferred. (b) State the charge on the hair. (c) Explain why the hairs stand apart from each other. Give only the answer to (a).' + take('e'), 0.40e-6 / QE, None,
  f'(a) N = 0.40 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = {sf(0.4e-6 / QE)}. (b) +0.40 µC, because charge is conserved. (c) Each hair loses electrons and is positively charged; like charges repel, so the hairs push apart.',
  ['C1: N = Q/e', 'B1: +0.40 µC on hair', 'B1: hairs have like charges', 'B1: like charges repel'], aq='N')
N('H', 5, 'A metal sphere on an insulating stand is charged by induction using a rod carrying +20 nC. While the rod is held near, the sphere is connected to earth and then disconnected; the rod is then removed. The sphere is left with a charge of −8.0 nC. (a) State the direction in which electrons flowed through the earth connection. (b) Calculate the number of electrons that flowed. (c) Explain why the sphere\'s charge is smaller in magnitude than the rod\'s. Give only the answer to (b).' + take('e'), 8.0e-9 / QE, None,
  f'(a) From the earth to the sphere, attracted by the positive rod. (b) N = 8.0 × 10⁻⁹ ÷ 1.60 × 10⁻¹⁹ = {sf(8e-9 / QE)}. (c) The rod is some distance away, so only part of its field ends on the sphere and fewer electrons are drawn up than would exactly balance it.',
  ['B1: electrons flow from earth to sphere', 'C1: N = Q/e', 'C1: substitution', 'B1: rod not touching, so induced charge smaller'], sig=2, aq='N')
N('H', 6, 'A small metal sphere carries +64 nC. It is touched with an identical uncharged sphere, which is then earthed to remove its charge. This is repeated. (a) Show that after n contacts the charge on the first sphere is 64/2ⁿ nC. (b) Calculate the charge after 5 contacts. (c) Calculate the number of contacts needed before the charge first falls below 1.0 nC. (d) Explain why the halving process cannot continue for ever. Give only the answer to (b).', 64 / 2 ** 5, 'nC',
  '(a) Each contact shares the charge equally, halving it, so after n contacts Q = 64 ÷ 2ⁿ nC. (b) Q = 64 ÷ 2⁵ = 2.0 nC. (c) 64 ÷ 2⁶ = 1.0 nC is not below 1.0 nC, but 64 ÷ 2⁷ = 0.50 nC is, so 7 contacts. (d) Charge is quantised in units of e = 1.6 × 10⁻¹⁹ C, so the charge cannot be shared into amounts smaller than one electron\'s charge.',
  ['M1: charge halves at each contact', 'C1: 64/2⁵', 'C1: 2⁶ gives 1.0 nC', 'A1: 7 contacts', 'B1: charge quantised in units of e'], sig=2, aq='Q')
N('H', 5, 'The electron gun in an old television tube produced a beam current of 0.80 mA. It ran for 2.0 hours. (a) Calculate the charge carried by the beam. (b) Calculate the number of electrons. (c) Calculate the total mass of these electrons, in units of 10⁻¹¹ kg. Give only the answer to (c).' + take('e', 'me'), 0.80e-3 * 7200 / QE * ME, '10⁻¹¹ kg',
  f'(a) Q = It = 0.80 × 10⁻³ × 7200 = {sf(0.8e-3 * 7200)} C. (b) N = {sf(0.8e-3 * 7200)} ÷ 1.60 × 10⁻¹⁹ = {sf(0.8e-3 * 7200 / QE)}. (c) m = {sf(0.8e-3 * 7200 / QE, 4)} × 9.11 × 10⁻³¹ = {sf(0.8e-3 * 7200 / QE * ME)} kg',
  ['C1: Q = It', 'C1: t = 7200 s', 'C1: N = Q/e', 'C1: m = Nmₑ'], aq='m')
N('H', 5, 'A crop sprayer charges each droplet to 2.0 × 10⁻¹² C and emits 4.0 × 10⁸ droplets per second. (a) Calculate the current carried by the spray, in mA. (b) Explain why the droplets spread out into a wide cloud. (c) Explain why charged droplets coat the undersides of leaves as well as the tops. Give only the answer to (a).', 2.0e-12 * 4.0e8 * 1000, 'mA',
  f'(a) I = 4.0 × 10⁸ × 2.0 × 10⁻¹² = {sf(8e-4)} A. In mA: 8.0 × 10⁻⁴ × 1000 = 0.80. (b) All the droplets carry the same sign of charge, so they repel each other. (c) The plants are earthed, so the droplets induce opposite charge on them and are attracted to all surfaces, curving round to the undersides.',
  ['C1: I = rate × charge', 'C1: conversion to mA', 'B1: like charges repel', 'B1: induced charge on earthed plant'], sig=2, aq='I')
N('H', 6, 'In an experiment like Millikan\'s, a student measures the charges on four oil drops as 4.9, 8.1, 11.3 and 16.0 × 10⁻¹⁹ C, each with an uncertainty of about ±0.2 × 10⁻¹⁹ C. (a) Divide each value by 1.6 × 10⁻¹⁹ C and comment on the results. (b) State the number of electronic charges on each drop. (c) Use all four results to calculate a value for the elementary charge, in units of 10⁻¹⁹ C. Give only the answer to (c).', (4.9 + 8.1 + 11.3 + 16.0) / (3 + 5 + 7 + 10) * 1e-19, '10⁻¹⁹ C',
  f'(a) 4.9 ÷ 1.6 = {sf(4.9 / 1.6)}, 8.1 ÷ 1.6 = {sf(8.1 / 1.6)}, 11.3 ÷ 1.6 = {sf(11.3 / 1.6)} and 16.0 ÷ 1.6 = 10.0: all close to whole numbers within the uncertainty. (b) 3, 5, 7 and 10. (c) e = total charge ÷ total number of electrons: (4.9 + 8.1 + 11.3 + 16.0) × 10⁻¹⁹ ÷ (3 + 5 + 7 + 10) = {sf(40.3 / 25 * 1e-19)} C',
  ['C1: ratios calculated', 'B1: close to integers', 'B1: 3, 5, 7, 10', 'M1: total charge ÷ total number', 'C1: substitution'], aq='e')

# ═════════════════════════ 21.2 Electric fields and field lines (15/15/12) ═════════════════════════
lesson('21.2')
M('E', 1, 'Which is the definition of electric field strength at a point?', 'The force per unit positive charge on a small charge placed at that point', ['The force on any charge placed at that point', 'The charge per unit force at that point', 'The work done per unit charge in bringing a charge to that point'], 'E = F/Q for a small positive test charge.')
M('E', 1, 'Which unit is a correct unit for electric field strength?', 'N C⁻¹', ['N C', 'C N⁻¹', 'J C'], 'E = F/Q, so N C⁻¹; this is equivalent to V m⁻¹.')
N('E', 2, 'A proton is at a point where the electric field strength is 2.5 × 10⁴ N C⁻¹. Calculate the force on it, in units of 10⁻¹⁵ N.' + take('e'), 2.5e4 * QE, '10⁻¹⁵ N',
  f'F = EQ = 2.5 × 10⁴ × 1.60 × 10⁻¹⁹ = {sf(2.5e4 * QE)} N', ['C1: F = EQ'], sig=2, aq='F')
N('E', 2, 'A dust particle with charge +3.0 nC experiences an electric force of 6.0 × 10⁻⁵ N. Calculate the electric field strength at its position.', 6.0e-5 / 3.0e-9, 'N C⁻¹',
  'E = F/Q = 6.0 × 10⁻⁵ ÷ 3.0 × 10⁻⁹ = 2.0 × 10⁴ N C⁻¹', ['C1: E = F/Q with Q in C'], sig=2, aq='E')
M('E', 1, 'Which describes the field lines around an isolated positive point charge?', 'Straight lines pointing radially outwards', ['Straight lines pointing radially inwards', 'Concentric circles around the charge', 'Parallel, equally spaced lines'], 'Field lines show the direction of the force on a positive test charge: away from a positive charge.')
M('E', 1, 'On an electric field diagram, what does the spacing of the field lines show?', 'The field strength: closer lines mean a stronger field', ['The amount of charge flowing', 'The speed of the charges', 'Nothing; only the direction matters'], 'Line density is proportional to field strength.')
N('E', 2, 'A charge of −5.0 µC is placed in a uniform electric field of strength 800 N C⁻¹. Calculate the magnitude of the force on it.', 5.0e-6 * 800, 'N',
  'F = EQ = 800 × 5.0 × 10⁻⁶ = 4.0 × 10⁻³ N, directed opposite to the field', ['C1: F = EQ'], sig=2, aq='F')
M('E', 1, 'The electric field at a point is directed due east. In which direction is the force on an electron at that point?', 'Due west', ['Due east', 'Due north', 'There is no force on an electron'], 'Field direction is the force direction on a positive charge; the electron is negative.')
M('E', 1, 'Two equal positive point charges are some distance apart. Where is the electric field zero?', 'At the midpoint between them', ['Nowhere', 'At each charge', 'At all points on the line joining them'], 'At the midpoint the equal fields from the two charges are opposite and cancel: a neutral point.')
N('E', 2, 'An oil droplet carrying a charge of 4.8 × 10⁻¹⁹ C experiences an electric force of 2.4 × 10⁻¹⁴ N. Calculate the field strength.', 2.4e-14 / 4.8e-19, 'N C⁻¹',
  'E = F/Q = 2.4 × 10⁻¹⁴ ÷ 4.8 × 10⁻¹⁹ = 5.0 × 10⁴ N C⁻¹', ['C1: E = F/Q'], sig=2, aq='E')
M('E', 1, 'At what angle do electric field lines meet the surface of a charged conductor?', 'At right angles', ['At 45°', 'Parallel to the surface', 'At any angle'], 'There is no field component along the surface of a conductor in equilibrium, or charges would move.')
M('E', 1, 'Why is electric field strength a vector quantity?', 'It has both magnitude and direction', ['It can only be positive', 'It is measured in newtons', 'It depends on time'], 'E has the direction of the force on a positive charge.')
N('E', 2, 'At a certain point the electric field strength is 1.2 × 10⁵ N C⁻¹. What charge would experience a force of 0.36 N there? Give your answer in µC.', 0.36 / 1.2e5 * 1e6, 'µC',
  'Q = F/E = 0.36 ÷ 1.2 × 10⁵ = 3.0 × 10⁻⁶ C. In µC: 3.0 × 10⁻⁶ × 10⁶ = 3.0', ['C1: Q = F/E'], sig=2, aq='Q')
M('E', 1, 'Which statement about gravitational and electric fields is correct?', 'Gravitational forces are always attractive, but electric forces can attract or repel', ['Both can attract or repel', 'Both are always attractive', 'Electric forces are always attractive, but gravitational forces can repel'], 'Mass is always positive; charge can be positive or negative.')
N('E', 1, 'A charge experiences a force of 2.0 mN in an electric field. The field strength is tripled. What is the new force, in mN?', 6.0, 'mN',
  'F = EQ, so tripling E triples F: 3 × 2.0 = 6.0 mN', [], sig=2, aq='F')
# medium
N('M', 3, 'At point P, one charged object produces a field of 3.0 × 10⁴ N C⁻¹ due east and a second produces a field of 4.0 × 10⁴ N C⁻¹ due north. Calculate the magnitude of the resultant field at P.', 5.0e4, 'N C⁻¹',
  'Fields add as vectors: E = √((3.0 × 10⁴)² + (4.0 × 10⁴)²) = 5.0 × 10⁴ N C⁻¹', ['M1: vector addition at right angles', 'C1: Pythagoras'], sig=2, aq='E')
N('M', 3, 'At a point, charge A produces a field of 6.0 × 10³ N C⁻¹ due east and charge B produces a field of 2.5 × 10³ N C⁻¹ due west. Calculate the magnitude of the force on an electron at this point, in units of 10⁻¹⁶ N.' + take('e'), (6.0e3 - 2.5e3) * QE, '10⁻¹⁶ N',
  f'Resultant E = 6.0 × 10³ − 2.5 × 10³ = 3.5 × 10³ N C⁻¹ east. F = 3.5 × 10³ × 1.60 × 10⁻¹⁹ = {sf(3.5e3 * QE)} N, directed west', ['C1: opposite fields subtract', 'C1: F = EQ'], sig=2, aq='F')
M('M', 3, 'A positive point charge is held above a large, flat, earthed metal plate. Which describes the field lines near the plate?', 'They curve from the charge and meet the plate at right angles', ['They run parallel to the plate', 'They pass through the plate into the region below', 'They meet the plate at 45°'], 'Lines start on the positive charge and end on induced negative charge on the plate, always perpendicular to a conductor\'s surface.', ['C1: lines end on induced charge', 'C1: perpendicular to conductor'])
N('M', 4, 'A small charged sphere of mass 2.0 × 10⁻⁴ kg hangs from an insulating thread in a uniform horizontal electric field of 4.0 × 10⁴ N C⁻¹. The thread makes an angle of 15° with the vertical. Calculate the charge on the sphere, in nC.' + take('g'), 2.0e-4 * g * tan(radians(15)) / 4.0e4 * 1e9, 'nC',
  f'Horizontally T sin 15° = QE and vertically T cos 15° = mg, so QE = mg tan 15°. Q = 2.0 × 10⁻⁴ × 9.81 × tan 15° ÷ 4.0 × 10⁴ = {sf(2e-4 * 9.81 * tan(radians(15)) / 4e4)} C. In nC: {sf(2e-4 * 9.81 * tan(radians(15)) / 4e4, 4)} × 10⁹ = {sf(2e-4 * 9.81 * tan(radians(15)) / 4e4 * 1e9)}',
  ['M1: resolve forces', 'C1: QE = mg tan θ', 'C1: substitution'], aq='Q')
M('M', 3, 'A pear-shaped metal conductor is charged. Where is the electric field just outside its surface strongest?', 'Near the most sharply curved, pointed end', ['Near the flattest part', 'It is the same everywhere', 'Inside the conductor'], 'Charge concentrates where curvature is greatest, so field lines are densest there; this is why lightning conductors are pointed.', ['C1: charge density highest at points', 'C1: field lines densest'])
N('M', 3, 'An α-particle (charge +2e, mass 6.64 × 10⁻²⁷ kg) is in an electric field of 2.0 × 10⁵ N C⁻¹. Calculate its acceleration.' + take('e'), 2 * QE * 2.0e5 / MA, 'm s⁻²',
  f'F = 2eE = 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = {sf(2 * QE * 2e5)} N. a = F/m = {sf(2 * QE * 2e5)} ÷ 6.64 × 10⁻²⁷ = {sf(2 * QE * 2e5 / MA)} m s⁻²', ['C1: charge = 2e', 'C1: a = F/m'], aq='a')
M('M', 3, 'A positive test charge is placed near a negatively charged sphere. Which statement is correct?', 'The field lines point towards the sphere and the test charge is pulled towards it', ['The field lines point away from the sphere and the test charge is pushed away', 'The field lines point towards the sphere but the test charge is pushed away', 'There is no field outside a negatively charged sphere'], 'Lines end on negative charge, and a positive charge moves along the field direction.', ['C1: lines end on negative charge', 'C1: positive charge moves along E'])
N('M', 4, 'A dust particle of mass 1.0 × 10⁻¹² kg carries 50 excess electrons. It is in an electric field of 2.0 × 10⁴ N C⁻¹. Ignoring gravity and air resistance, calculate its acceleration.' + take('e'), 50 * QE * 2.0e4 / 1.0e-12, 'm s⁻²',
  f'Q = 50 × 1.60 × 10⁻¹⁹ = {sf(50 * QE)} C. F = EQ = 2.0 × 10⁴ × {sf(50 * QE)} = {sf(2e4 * 50 * QE)} N. a = {sf(2e4 * 50 * QE)} ÷ 1.0 × 10⁻¹² = {sf(2e4 * 50 * QE / 1e-12)} m s⁻²', ['C1: Q = Ne', 'C1: F = EQ', 'C1: a = F/m'], sig=2, aq='a')
M('M', 4, 'Why should the test charge used to measure an electric field be very small?', 'So that it does not disturb the charges that produce the field being measured', ['So that it does not fall under gravity', 'So that the force on it is large', 'Because large charges have no field'], 'A large test charge would push or pull the source charges, changing the field it was meant to measure.', ['C1: test charge exerts forces too', 'C1: source charges could move', 'C1: field would change'])
N('M', 3, 'Near the Earth\'s surface in fine weather there is an electric field of about 130 N C⁻¹. Calculate the ratio of the electric force on an electron in this field to the electron\'s weight.' + take('e', 'me', 'g'), 130 * QE / (ME * g), None,
  f'F_E = 130 × 1.60 × 10⁻¹⁹ = {sf(130 * QE)} N. W = 9.11 × 10⁻³¹ × 9.81 = {sf(ME * 9.81)} N. Ratio = {sf(130 * QE, 4)} ÷ {sf(ME * 9.81, 4)} = {sf(130 * QE / (ME * 9.81))}', ['C1: F = eE', 'C1: W = mg'], aq='ratio')
M('M', 3, 'A positive and a negative point charge of equal magnitude are placed a short distance apart. What is the direction of the electric field at the midpoint between them?', 'Along the line joining them, towards the negative charge', ['Along the line joining them, towards the positive charge', 'Perpendicular to the line joining them', 'There is no field at the midpoint'], 'Both fields point the same way at the midpoint: away from + and towards −, so they add.', ['C1: both fields point the same way', 'C1: towards the negative charge'])
N('M', 3, 'A charge of +2.0 µC at point P experiences a force of 0.050 N to the left. The +2.0 µC charge is replaced by a charge of −6.0 µC. Calculate the magnitude of the force on the new charge.', 0.050 / 2.0e-6 * 6.0e-6, 'N',
  'E = F/Q = 0.050 ÷ 2.0 × 10⁻⁶ = 2.5 × 10⁴ N C⁻¹ to the left. F = 2.5 × 10⁴ × 6.0 × 10⁻⁶ = 0.15 N, to the right', ['C1: E = F/Q', 'C1: F = EQ for new charge'], sig=2, aq='F')
M('M', 3, 'Near the ground the Earth\'s fair-weather electric field points vertically downwards. What does this show about the charge on the Earth\'s surface?', 'It is negative', ['It is positive', 'It is zero', 'It changes sign every second'], 'Field lines end on negative charge, so downward lines end on a negatively charged ground.', ['C1: lines end on negative charge', 'C1: downward field'])
N('M', 4, 'At a point, the electric field has a horizontal component of 2.0 × 10³ N C⁻¹ and a vertically upward component of 5.0 × 10³ N C⁻¹. Calculate the angle the resultant field makes with the horizontal.', degrees(atan(2.5)), '°',
  f'tan θ = 5.0 × 10³ ÷ 2.0 × 10³ = 2.5, so θ = tan⁻¹ 2.5 = {sf(degrees(atan(2.5)))}°', ['M1: field components combine as vectors', 'C1: tan θ = E_y/E_x', 'C1: inverse tangent'], aq='θ')
M('M', 3, 'Which describes the electric field near the middle of a large, flat, positively charged plate?', 'Parallel lines perpendicular to the plate, pointing away from it, equally spaced', ['Radial lines spreading out from the centre of the plate', 'Lines parallel to the plate surface', 'Concentric circles around the plate'], 'Far from the edges, a large plate produces a uniform field perpendicular to its surface.', ['C1: perpendicular, away from + plate', 'C1: uniform spacing'])
# hard
N('H', 6, 'A small sphere of mass 3.0 × 10⁻⁴ kg carries a charge of +25 nC and hangs from an insulating thread. A uniform horizontal electric field is switched on and the thread settles at 10° to the vertical. (a) Draw and label the forces on the sphere (describe them in words). (b) Calculate the electric field strength. (c) Calculate the tension in the thread. Give only the answer to (b).' + take('g'), 3.0e-4 * g * tan(radians(10)) / 25e-9, 'N C⁻¹',
  f'(a) Weight mg downwards, tension T along the thread, and electric force QE horizontally in the direction of the field. (b) QE = mg tan 10°, so E = 3.0 × 10⁻⁴ × 9.81 × tan 10° ÷ 25 × 10⁻⁹ = {sf(3e-4 * 9.81 * tan(radians(10)) / 25e-9)} N C⁻¹. (c) T = mg ÷ cos 10° = 3.0 × 10⁻⁴ × 9.81 ÷ cos 10° = {sf(3e-4 * 9.81 / cos(radians(10)))} N',
  ['B1: three forces identified', 'M1: resolve: QE = mg tan θ', 'C1: substitution with Q in C', 'C1: T = mg/cos θ', 'A1: tension value'], aq='E')
N('H', 6, 'At point P, charge A produces an electric field of 8.0 × 10⁴ N C⁻¹ in the +x direction. Charge B produces a field of 6.0 × 10⁴ N C⁻¹ directed at 60° above the −x direction. (a) Calculate the x- and y-components of the resultant field. (b) Calculate the magnitude of the resultant field. (c) Calculate the magnitude of the force on an electron at P, in units of 10⁻¹⁵ N. Give only the answer to (b).' + take('e'), sqrt((8.0e4 - 6.0e4 * cos(radians(60))) ** 2 + (6.0e4 * sin(radians(60))) ** 2), 'N C⁻¹',
  f'(a) E_x = 8.0 × 10⁴ − 6.0 × 10⁴ × cos 60° = 5.0 × 10⁴ N C⁻¹. E_y = 6.0 × 10⁴ × sin 60° = {sf(6e4 * sin(radians(60)))} N C⁻¹. (b) E = √((5.0 × 10⁴)² + ({sf(6e4 * sin(radians(60)), 4)})²) = {sf(sqrt(5e4 ** 2 + (6e4 * sin(radians(60))) ** 2))} N C⁻¹. (c) F = 1.60 × 10⁻¹⁹ × {sf(sqrt(5e4 ** 2 + (6e4 * sin(radians(60))) ** 2), 4)} = {sf(QE * sqrt(5e4 ** 2 + (6e4 * sin(radians(60))) ** 2))} N',
  ['C1: x-component', 'C1: y-component', 'M1: Pythagoras on components', 'C1: F = eE', 'A1: force value'], aq='E')
N('H', 5, 'An electron and a proton are released from rest at the same point in a uniform electric field of 1.5 × 10³ N C⁻¹. (a) Compare the magnitudes and directions of the forces on them. (b) Calculate the acceleration of the electron. (c) Calculate the ratio (acceleration of electron) ÷ (acceleration of proton). Give only the answer to (c).' + take('e', 'me', 'mp'), MP / ME, None,
  f'(a) Equal magnitudes, eE, in opposite directions: the proton along the field, the electron against it. (b) a = eE/m = 1.60 × 10⁻¹⁹ × 1.5 × 10³ ÷ 9.11 × 10⁻³¹ = {sf(QE * 1.5e3 / ME)} m s⁻². (c) Same force, so a ∝ 1/m: ratio = 1.67 × 10⁻²⁷ ÷ 9.11 × 10⁻³¹ = {sf(MP / ME)}',
  ['B1: equal and opposite forces', 'C1: a = eE/m', 'M1: same F so a ∝ 1/m', 'C1: mass ratio'], aq='ratio')
N('H', 6, 'A probe measures the force on a test charge of 2.0 nC at different distances r from the centre of a charged sphere: r = 0.10, 0.20 and 0.30 m; F = 7.2 × 10⁻⁴, 1.8 × 10⁻⁴ and 8.0 × 10⁻⁵ N. (a) Calculate the field strength at each distance. (b) Show that the field strength is inversely proportional to r². (c) Predict the field strength at r = 0.40 m. Give only the answer to (c).', 3.6e5 * (0.10 / 0.40) ** 2, 'N C⁻¹',
  f'(a) E = F/q: 7.2 × 10⁻⁴ ÷ 2.0 × 10⁻⁹ = 3.6 × 10⁵ N C⁻¹; 1.8 × 10⁻⁴ ÷ 2.0 × 10⁻⁹ = 9.0 × 10⁴ N C⁻¹; 8.0 × 10⁻⁵ ÷ 2.0 × 10⁻⁹ = 4.0 × 10⁴ N C⁻¹. (b) Er² = 3.6 × 10⁵ × 0.10² = 3600 N m² C⁻¹ for every reading, so E ∝ 1/r². (c) E = 3600 ÷ 0.40² = {sf(3600 / 0.16)} N C⁻¹',
  ['C1: E = F/q for each reading', 'B1: Er² constant', 'M1: E ∝ 1/r²', 'C1: substitution at 0.40 m', 'C1: field lines spread out, consistent with radial field'], aq='E')
N('H', 5, 'In an electrostatic precipitator, a smoke particle of mass 2.0 × 10⁻¹³ kg carries a charge of 8.0 × 10⁻¹⁷ C. It is in a field of 5.0 × 10⁵ N C⁻¹ and starts from rest, 0.10 m from a collecting plate. (a) Calculate the electric force on the particle. (b) Calculate its acceleration. (c) Ignoring gravity and air resistance, calculate the time taken to reach the plate, in ms. Give only the answer to (c).', sqrt(2 * 0.10 / (8.0e-17 * 5.0e5 / 2.0e-13)) * 1000, 'ms',
  f'(a) F = EQ = 5.0 × 10⁵ × 8.0 × 10⁻¹⁷ = 4.0 × 10⁻¹¹ N. (b) a = 4.0 × 10⁻¹¹ ÷ 2.0 × 10⁻¹³ = 200 m s⁻². (c) s = ½at², so t = √(2 × 0.10 ÷ 200) = {sf(sqrt(0.2 / 200))} s. In ms: {sf(sqrt(0.2 / 200), 4)} × 1000 = {sf(sqrt(0.2 / 200) * 1000)}',
  ['C1: F = EQ', 'C1: a = F/m', 'M1: s = ½at² from rest', 'C1: rearranged for t'], aq='t')
N('H', 6, 'In fine weather there is a downward electric field of 120 N C⁻¹ near the ground. A pollen grain of mass 2.0 × 10⁻¹⁴ kg floats without rising or falling, supported only by the electric force. (a) State whether the grain\'s charge is positive or negative, and explain. (b) Calculate the charge needed. (c) Calculate the number of electrons this charge represents. Give only the answer to (c).' + take('g', 'e'), 2.0e-14 * g / 120 / QE, None,
  f'(a) Negative: the electric force must be upwards, opposite to the downward field. (b) QE = mg, so Q = 2.0 × 10⁻¹⁴ × 9.81 ÷ 120 = {sf(2e-14 * 9.81 / 120)} C. (c) N = {sf(2e-14 * 9.81 / 120, 4)} ÷ 1.60 × 10⁻¹⁹ = {sf(2e-14 * 9.81 / 120 / QE)}',
  ['B1: negative, force opposite to field', 'M1: QE = mg', 'C1: Q value', 'C1: N = Q/e', 'B1: plausible number of electrons'], aq='N')
N('H', 5, '(a) State one similarity and one difference between electric field strength and gravitational field strength. (b) Calculate the electric field strength that would support an electron against its own weight near the Earth\'s surface, in units of 10⁻¹¹ N C⁻¹. (c) Comment on why gravitational effects on electrons are usually ignored. Give only the answer to (b).' + take('me', 'g', 'e'), ME * g / QE, '10⁻¹¹ N C⁻¹',
  f'(a) Both are force per unit of the property (charge or mass) and both are vectors; electric forces can repel, gravitational forces only attract. (b) eE = mₑg, so E = 9.11 × 10⁻³¹ × 9.81 ÷ 1.60 × 10⁻¹⁹ = {sf(ME * 9.81 / QE)} N C⁻¹. (c) Even very weak electric fields, such as the 100 N C⁻¹ fair-weather field, give forces about 10¹² times larger.',
  ['B1: similarity', 'B1: difference', 'C1: eE = mg', 'B1: tiny field needed so gravity negligible'], aq='E')
N('H', 5, 'A test charge of 5.0 nC at point P experiences a force of 3.0 × 10⁻⁴ N directed at 30° above the +x axis. (a) Calculate the field strength at P. (b) Calculate the x-component of the field. (c) State the magnitude and direction of the force on a −2.0 nC charge placed at P instead. Give only the answer to (b).', 3.0e-4 / 5.0e-9 * cos(radians(30)), 'N C⁻¹',
  f'(a) E = F/q = 3.0 × 10⁻⁴ ÷ 5.0 × 10⁻⁹ = 6.0 × 10⁴ N C⁻¹. (b) E_x = 6.0 × 10⁴ × cos 30° = {sf(6e4 * cos(radians(30)))} N C⁻¹. (c) F = 6.0 × 10⁴ × 2.0 × 10⁻⁹ = 1.2 × 10⁻⁴ N, directed at 30° below the −x axis, opposite to the field.',
  ['C1: E = F/q', 'C1: E_x = E cos 30°', 'C1: force magnitude on new charge', 'B1: reversed direction'], aq='E_x')
N('H', 6, 'In a mass spectrometer, singly charged sodium ions (mass 3.82 × 10⁻²⁶ kg) and potassium ions (mass 6.49 × 10⁻²⁶ kg) start from rest in a uniform field of 2.0 × 10⁴ N C⁻¹. (a) Calculate the force on each ion. (b) Calculate the speed of a sodium ion after 1.0 µs. (c) Calculate the ratio of the speeds (sodium ÷ potassium) at the same time. Give only the answer to (b), in km s⁻¹.' + take('e'), QE * 2.0e4 * 1.0e-6 / 3.82e-26 / 1000, 'km s⁻¹',
  f'(a) F = eE = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ = {sf(QE * 2e4)} N for both ions. (b) v = at = Ft/m = {sf(QE * 2e4)} × 1.0 × 10⁻⁶ ÷ 3.82 × 10⁻²⁶ = {sf(QE * 2e4 * 1e-6 / 3.82e-26)} m s⁻¹. In km s⁻¹: {sf(QE * 2e4 * 1e-6 / 3.82e-26, 4)} ÷ 1000 = {sf(QE * 2e4 * 1e-6 / 3.82e-26 / 1000)}. (c) Same force and time, so v ∝ 1/m: ratio = 6.49 ÷ 3.82 = {sf(6.49 / 3.82)}',
  ['C1: F = eE', 'M1: v = (F/m)t from rest', 'C1: substitution', 'C1: unit conversion', 'C1: v ∝ 1/m ratio'], aq='v')
N('H', 5, 'A field-line diagram is drawn so that the number of lines leaving or ending on a charge is proportional to the charge. Twelve lines leave sphere A, which carries +6.0 nC. Four of these lines end on a nearby sphere B; the rest go off to large distances. No lines leave B. (a) Calculate the charge on B. (b) Explain how you know the sign of B\'s charge. (c) State where the field near A is strongest and how the diagram shows this. Give only the magnitude of the answer to (a), in nC.', 6.0 * 4 / 12, 'nC',
  '(a) Each line represents 6.0 ÷ 12 = 0.50 nC, so B carries 4 × 0.50 = 2.0 nC. (b) Lines end on B, and field lines end on negative charge, so B is −2.0 nC. (c) Close to A\'s surface, where the lines are closest together.',
  ['C1: charge per line', 'C1: 4 lines on B', 'B1: lines end on negative charge', 'B1: strongest where lines densest'], sig=2, aq='Q_B')
N('H', 5, 'A proton and an α-particle (charge +2e, mass 6.64 × 10⁻²⁷ kg) are released from rest in the same uniform electric field. The proton mass is 1.67 × 10⁻²⁷ kg. (a) Calculate the ratio of the forces (α ÷ proton). (b) Calculate the ratio of their accelerations (α ÷ proton). (c) State the ratio of their kinetic energies after each has moved the same distance, and explain. Give only the answer to (b).', 2 * MP / MA, None,
  f'(a) Force ratio = 2e ÷ e = 2. (b) Acceleration ratio = (2e ÷ 6.64 × 10⁻²⁷) ÷ (e ÷ 1.67 × 10⁻²⁷) = 2 × 1.67 ÷ 6.64 = {sf(2 * 1.67 / 6.64)}. (c) KE gained = work done = F × distance, so the α-particle gains twice the kinetic energy.',
  ['C1: force ratio 2', 'M1: a = qE/m', 'C1: substitution', 'B1: KE = Fd so ratio 2'], aq='ratio')
N('H', 6, 'To measure the field at a fixed point, a student places different small test charges there and measures the force: q/nC = 1.0, 2.0, 3.0, 4.0 and F/µN = 24, 49, 71, 97. (a) Describe the graph of F against q. (b) Calculate the gradient of the graph from the first and last readings. (c) Use the gradient to find the field strength. (d) Explain why the student should not use a much larger test charge. Give only the answer to (c).', (97 - 24) * 1e-6 / ((4.0 - 1.0) * 1e-9), 'N C⁻¹',
  f'(a) A straight line through the origin, so F ∝ q. (b) Gradient = (97 − 24) × 10⁻⁶ ÷ ((4.0 − 1.0) × 10⁻⁹) = {sf(73e-6 / 3e-9)} N C⁻¹. (c) F = Eq, so E = gradient = {sf(73e-6 / 3e-9)} N C⁻¹. (d) A large test charge would exert forces on the source charges and change the field it was meant to measure.',
  ['B1: straight line through origin', 'C1: gradient with units converted', 'M1: E = gradient', 'B1: large q disturbs field', 'C1: substitution'], aq='E')

# ═════════════════════════ 21.3 Uniform electric fields (15/17/10) ═════════════════════════
lesson('21.3')
N('E', 2, 'The two parallel plates in an ink-jet printer head are 0.50 mm apart and have 150 V between them. Calculate the electric field strength between the plates.', 150 / 0.50e-3, 'V m⁻¹',
  'E = V/d = 150 ÷ 0.50 × 10⁻³ = 3.0 × 10⁵ V m⁻¹', ['C1: E = V/d with d in m'], sig=2, aq='E')
M('E', 1, 'How are the field lines drawn in the central region between two parallel plates connected to a supply?', 'Parallel, equally spaced, from the positive plate to the negative plate', ['Radial lines from the centre of each plate', 'Curved lines that cross in the middle', 'Parallel lines from the negative plate to the positive plate'], 'A uniform field is shown by parallel, equally spaced lines pointing from + to −.')
M('E', 1, 'The separation of two parallel plates is doubled while the p.d. between them is kept constant. What happens to the field strength between them?', 'It halves', ['It doubles', 'It stays the same', 'It quarters'], 'E = V/d: with V fixed, doubling d halves E.')
N('E', 2, 'Dry air breaks down and conducts when the field strength reaches 3.0 × 10⁶ V m⁻¹. Calculate the largest p.d. that can be applied across an air gap of 2.0 mm without sparking.', 3.0e6 * 2.0e-3, 'V',
  'V = Ed = 3.0 × 10⁶ × 2.0 × 10⁻³ = 6000 V', ['C1: V = Ed'], sig=2, aq='V')
M('E', 1, 'Which unit is equivalent to V m⁻¹?', 'N C⁻¹', ['N C', 'J m', 'C N⁻¹'], '1 V = 1 J C⁻¹, so V m⁻¹ = J C⁻¹ m⁻¹ = N C⁻¹.')
N('E', 2, 'An electron is accelerated from rest through a p.d. of 2000 V. Calculate the kinetic energy it gains, in units of 10⁻¹⁶ J.' + take('e'), 2000 * QE, '10⁻¹⁶ J',
  f'E_k = eV = 1.60 × 10⁻¹⁹ × 2000 = {sf(2000 * QE)} J', ['C1: W = QV'], sig=2, aq='E_k')
M('E', 1, 'An electron is released from rest close to the negative plate of a pair of parallel plates in a vacuum. How does it move?', 'It accelerates uniformly towards the positive plate', ['It moves at constant speed towards the positive plate', 'It accelerates towards the negative plate', 'It stays at rest'], 'The uniform field gives a constant force and so a constant acceleration, towards the positive plate for a negative charge.')
N('E', 2, 'Before a thunderstorm, the field between the base of a cloud and the ground 800 m below is roughly uniform at 1.5 × 10⁴ V m⁻¹. Calculate the p.d. between the cloud base and the ground.', 1.5e4 * 800, 'V',
  'V = Ed = 1.5 × 10⁴ × 800 = 1.2 × 10⁷ V', ['C1: V = Ed'], sig=2, aq='V')
M('E', 1, 'What happens to the electric field near the edges of a pair of parallel plates?', 'The field lines curve outwards and the field is no longer uniform', ['The field becomes stronger and stays uniform', 'The field is zero', 'The field lines become parallel to the plates'], 'Edge effects make the field non-uniform; only the central region is uniform.')
N('E', 2, 'A proton travels from the positive plate to the negative plate of a pair with a p.d. of 500 V between them. Calculate the kinetic energy it gains, in units of 10⁻¹⁷ J.' + take('e'), 500 * QE, '10⁻¹⁷ J',
  f'E_k = eV = 1.60 × 10⁻¹⁹ × 500 = {sf(500 * QE)} J', ['C1: W = QV'], sig=2, aq='E_k')
M('E', 1, 'The p.d. between two parallel plates is doubled at constant separation. What happens to the force on a charged particle between them?', 'It doubles', ['It halves', 'It stays the same', 'It quadruples'], 'F = QE = QV/d, so at fixed d the force is proportional to V.')
N('E', 2, 'A cell membrane is 7.0 nm thick and has a p.d. of 70 mV across it. Treating it as a uniform field, calculate the field strength in the membrane.', 70e-3 / 7.0e-9, 'V m⁻¹',
  'E = V/d = 70 × 10⁻³ ÷ 7.0 × 10⁻⁹ = 1.0 × 10⁷ V m⁻¹', ['C1: E = V/d with units converted'], sig=2, aq='E')
M('E', 1, 'Which describes the graph of electric potential against distance across the gap between two parallel plates?', 'A straight line', ['A curve that gets steeper', 'A horizontal line', 'A curve that levels off'], 'In a uniform field the potential changes by the same amount for each metre: V varies linearly with distance.')
N('E', 2, 'Parallel plates 0.030 m apart have a p.d. of 600 V. Calculate the force on a charge of 4.0 µC between them.', 600 / 0.030 * 4.0e-6, 'N',
  'E = 600 ÷ 0.030 = 2.0 × 10⁴ V m⁻¹. F = EQ = 2.0 × 10⁴ × 4.0 × 10⁻⁶ = 0.080 N', ['C1: E = V/d then F = EQ'], sig=2, aq='F')
M('E', 1, 'A small charged particle is moved to different positions in the central region between two parallel plates. How does the electric force on it change?', 'It stays the same everywhere in the uniform field', ['It is largest near the positive plate', 'It is largest near the negative plate', 'It is largest midway between the plates'], 'In a uniform field E is the same at every point, so F = QE is constant.')
# medium
N('M', 3, 'An electron is accelerated from rest through a p.d. of 500 V. Calculate its final speed.' + take('e', 'me'), sqrt(2 * QE * 500 / ME), 'm s⁻¹',
  f'½mv² = eV, so v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 500 ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 500 / ME))} m s⁻¹', ['M1: ½mv² = eV', 'C1: substitution'], aq='v')
N('M', 4, 'Two parallel plates are 2.0 cm apart with a p.d. of 400 V between them. Calculate the acceleration of an electron between the plates.' + take('e', 'me'), QE * 400 / 0.020 / ME, 'm s⁻²',
  f'E = V/d = 400 ÷ 0.020 = 2.0 × 10⁴ V m⁻¹. F = eE = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ = {sf(QE * 2e4)} N. a = F/m = {sf(QE * 2e4)} ÷ 9.11 × 10⁻³¹ = {sf(QE * 2e4 / ME)} m s⁻²',
  ['C1: E = V/d', 'C1: F = eE', 'C1: a = F/m'], aq='a')
M('M', 3, 'Both the p.d. between two parallel plates and their separation are doubled. What happens to the field strength?', 'It stays the same', ['It doubles', 'It quadruples', 'It halves'], 'E = V/d: doubling both leaves the ratio unchanged.', ['C1: E = V/d', 'C1: ratio unchanged'])
N('M', 3, 'In the first stage of a particle accelerator, protons starting at rest gain energy from a 1.0 kV potential difference. What speed do they reach?' + take('e', 'mp'), sqrt(2 * QE * 1000 / MP), 'm s⁻¹',
  f'v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 1000 ÷ 1.67 × 10⁻²⁷) = {sf(sqrt(2 * QE * 1000 / MP))} m s⁻¹', ['M1: ½mv² = eV', 'C1: substitution'], aq='v')
N('M', 3, 'An electron starts from rest at the negative plate of a pair of parallel plates 1.0 cm apart. The field strength is 5.0 × 10³ V m⁻¹. Calculate the time it takes to reach the positive plate, in ns.' + take('e', 'me'), sqrt(2 * 0.010 / (QE * 5.0e3 / ME)) * 1e9, 'ns',
  f'a = eE/m = 1.60 × 10⁻¹⁹ × 5.0 × 10³ ÷ 9.11 × 10⁻³¹ = {sf(QE * 5e3 / ME)} m s⁻². t = √(2d/a) = √(2 × 0.010 ÷ {sf(QE * 5e3 / ME, 4)}) = {sf(sqrt(0.02 / (QE * 5e3 / ME)))} s. In ns: {sf(sqrt(0.02 / (QE * 5e3 / ME)), 4)} × 10⁹ = {sf(sqrt(0.02 / (QE * 5e3 / ME)) * 1e9)}', ['C1: a = eE/m', 'C1: s = ½at²'], aq='t')
M('M', 3, 'An electron enters the uniform field between two horizontal plates, moving horizontally. The upper plate is positive. Which statement about its motion is correct?', 'Its horizontal velocity stays constant while it accelerates upwards, so it follows a parabola', ['It moves in a circle', 'It slows down horizontally and stops', 'It moves in a straight line towards the lower plate'], 'The force is vertical and constant, like gravity on a projectile, but towards the positive plate.', ['C1: constant force perpendicular to initial velocity', 'C1: parabolic path towards + plate'])
N('M', 3, 'In a petrol engine, the spark plug gap is 0.80 mm. In the compressed fuel–air mixture, sparking needs a field strength of about 1.0 × 10⁷ V m⁻¹. Calculate the minimum p.d. needed across the gap.', 1.0e7 * 0.80e-3, 'V',
  'V = Ed = 1.0 × 10⁷ × 0.80 × 10⁻³ = 8000 V', ['C1: V = Ed', 'C1: gap in m'], sig=2, aq='V')
N('M', 3, 'The electron gun of an X-ray tube accelerates electrons through 5.0 kV, and the beam current is 2.0 mA. Calculate the energy delivered to the target by the beam each second.', 5.0e3 * 2.0e-3, 'W',
  'Each coulomb gains 5.0 × 10³ J, and 2.0 × 10⁻³ C arrives each second: P = IV = 2.0 × 10⁻³ × 5.0 × 10³ = 10 W', ['C1: energy per coulomb = V', 'C1: P = IV'], sig=2, aq='P')
N('M', 3, 'Calculate the field strength needed to give an electron an acceleration of 1.0 × 10¹⁵ m s⁻².' + take('e', 'me'), ME * 1.0e15 / QE, 'V m⁻¹',
  f'eE = ma, so E = ma/e = 9.11 × 10⁻³¹ × 1.0 × 10¹⁵ ÷ 1.60 × 10⁻¹⁹ = {sf(ME * 1e15 / QE)} V m⁻¹', ['M1: eE = ma', 'C1: substitution'], aq='E')
M('M', 3, 'Two parallel plates stay connected to a constant-voltage supply. The plates are moved closer together until the separation is halved. Which row is correct?', 'p.d. unchanged; field strength doubles', ['p.d. halves; field strength unchanged', 'p.d. doubles; field strength doubles', 'p.d. unchanged; field strength halves'], 'The supply fixes V, so E = V/d doubles when d halves.', ['C1: V fixed by supply', 'C1: E = V/d'])
N('M', 3, 'Two parallel plates are 10 cm apart. One is at 0 V and the other at +200 V. Calculate the potential at a point 3.0 cm from the 0 V plate.', 200 * 3.0 / 10, 'V',
  'The potential rises uniformly: V = 200 × 3.0 ÷ 10 = 60 V', ['C1: uniform potential gradient', 'C1: proportion of the distance'], sig=2, aq='V')
N('M', 3, 'An α-particle (charge +2e) is accelerated from rest through a p.d. of 2.0 kV. Calculate the kinetic energy it gains, in keV.', 2 * QE * 2.0e3 / 1.6e-16, 'keV',
  'E_k = QV = 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10³ = 6.4 × 10⁻¹⁶ J. In keV: 6.4 × 10⁻¹⁶ ÷ 1.6 × 10⁻¹⁶ = 4.0', ['C1: Q = 2e', 'C1: W = QV'], sig=2, cm='Using Q = e gives 2.0 keV: the α-particle carries two units of charge.', aq='E_k')
M('M', 3, 'Why can the weight of an electron be ignored when it moves between charged parallel plates?', 'The electric force (about 10⁻¹⁵ N in typical fields) is many orders of magnitude larger than its weight (about 10⁻²⁹ N)', ['Electrons have no mass', 'Gravity does not act in a vacuum', 'The electric force cancels the weight exactly'], 'mₑg ≈ 9 × 10⁻³⁰ N, which is negligible compared with eE.', ['C1: compares magnitudes', 'C1: weight negligible'])
N('M', 4, 'Two horizontal plates produce a uniform downward field of 5.0 × 10⁴ V m⁻¹. A charge of +2.0 µC is moved from a point 1.0 cm above the lower plate to a point 4.0 cm above it and 3.0 cm to one side. Calculate the work done against the electric force.', 2.0e-6 * 5.0e4 * 0.030, 'J',
  'Only the displacement along the field matters. The charge rises 4.0 − 1.0 = 3.0 cm against the field: W = QEΔx = 2.0 × 10⁻⁶ × 5.0 × 10⁴ × 0.030 = 3.0 × 10⁻³ J', ['M1: only component along E counts', 'C1: Δx = 3.0 cm', 'C1: W = QEΔx'], sig=2, aq='W')
M('M', 3, 'Which describes the graph of electric field strength against position across the gap between two parallel plates (away from the edges)?', 'A horizontal line', ['A straight line through the origin', 'A curve that falls with distance', 'A curve that rises with distance'], 'The field is uniform, so E has the same value at every point.', ['C1: uniform field', 'C1: constant E'])
N('M', 3, 'An electron moving at 3.0 × 10⁶ m s⁻¹ heads straight towards a negatively charged plate. Calculate the p.d. that would just bring it to rest.' + take('e', 'me'), 0.5 * ME * 3.0e6 ** 2 / QE, 'V',
  f'eV = ½mv², so V = 0.5 × 9.11 × 10⁻³¹ × (3.0 × 10⁶)² ÷ 1.60 × 10⁻¹⁹ = {sf(0.5 * ME * 9e12 / QE)} V', ['M1: eV = ½mv²', 'C1: substitution'], aq='V')
N('M', 3, 'An electron starts at rest on the negative plate and reaches the positive plate with a speed of 8.0 × 10⁶ m s⁻¹. Calculate the p.d. between the plates.' + take('e', 'me'), 0.5 * ME * 8.0e6 ** 2 / QE, 'V',
  f'V = ½mv²/e = 0.5 × 9.11 × 10⁻³¹ × (8.0 × 10⁶)² ÷ 1.60 × 10⁻¹⁹ = {sf(0.5 * ME * 6.4e13 / QE)} V', ['M1: eV = ½mv²', 'C1: substitution'], aq='V')
# hard
N('H', 6, 'An electron moving horizontally at 2.0 × 10⁷ m s⁻¹ enters the uniform field between two horizontal plates 5.0 cm long. The field strength between the plates is 1.0 × 10⁴ V m⁻¹. (a) Calculate the time the electron spends between the plates. (b) Calculate its vertical acceleration. (c) Calculate its vertical deflection as it leaves the plates, in mm. Give only the answer to (c).' + take('e', 'me'), 0.5 * (QE * 1.0e4 / ME) * (0.050 / 2.0e7) ** 2 * 1000, 'mm',
  f'(a) t = 0.050 ÷ 2.0 × 10⁷ = 2.5 × 10⁻⁹ s. (b) a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10⁴ ÷ 9.11 × 10⁻³¹ = {sf(QE * 1e4 / ME)} m s⁻². (c) y = ½at² = 0.5 × {sf(QE * 1e4 / ME, 4)} × (2.5 × 10⁻⁹)² = {sf(0.5 * QE * 1e4 / ME * 6.25e-18)} m. In mm: {sf(0.5 * QE * 1e4 / ME * 6.25e-18, 4)} × 1000 = {sf(0.5 * QE * 1e4 / ME * 6.25e-18 * 1000)}',
  ['C1: horizontal velocity constant, t = L/v', 'C1: a = eE/m', 'M1: y = ½at²', 'C1: substitution', 'C1: conversion to mm'], aq='y')
N('H', 7, 'Electrons are accelerated from rest through 1500 V. They then pass midway between two horizontal plates that are 4.0 cm long, 1.0 cm apart and have 60 V between them. (a) Calculate the speed of the electrons entering the plates. (b) Calculate the time spent between the plates. (c) Calculate the field strength and the vertical acceleration. (d) Calculate the vertical deflection on leaving the plates, in mm. Give only the answer to (d).' + take('e', 'me'),
  0.5 * (QE * 6000 / ME) * (0.040 / sqrt(2 * QE * 1500 / ME)) ** 2 * 1000, 'mm',
  f'(a) v = √(2 × 1.60 × 10⁻¹⁹ × 1500 ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 1500 / ME))} m s⁻¹. (b) t = 0.040 ÷ {sf(sqrt(2 * QE * 1500 / ME), 4)} = {sf(0.04 / sqrt(2 * QE * 1500 / ME))} s. (c) E = 60 ÷ 0.010 = 6000 V m⁻¹; a = 1.60 × 10⁻¹⁹ × 6000 ÷ 9.11 × 10⁻³¹ = {sf(QE * 6000 / ME)} m s⁻². (d) y = ½at² = 0.5 × {sf(QE * 6000 / ME, 4)} × ({sf(0.04 / sqrt(2 * QE * 1500 / ME), 4)})² = {sf(0.5 * QE * 6000 / ME * (0.04 / sqrt(2 * QE * 1500 / ME)) ** 2)} m. In mm: {sf(0.5 * QE * 6000 / ME * (0.04 / sqrt(2 * QE * 1500 / ME)) ** 2, 4)} × 1000 = {sf(0.5 * QE * 6000 / ME * (0.04 / sqrt(2 * QE * 1500 / ME)) ** 2 * 1000)}',
  ['C1: ½mv² = eV', 'C1: t = L/v', 'C1: E = V/d', 'C1: a = eE/m', 'M1: y = ½at²', 'C1: conversion to mm'], aq='y')
N('H', 5, 'Before a lightning strike, the p.d. between a cloud base and the ground 2.0 km below is 1.0 × 10⁸ V. (a) Calculate the average field strength between the cloud and the ground. (b) Air breaks down at about 3.0 × 10⁶ V m⁻¹. Suggest why lightning can still occur. (c) The flash transfers 20 C through the full p.d. Calculate the energy transferred. Give only the answer to (c).', 20 * 1.0e8, 'J',
  '(a) E = V/d = 1.0 × 10⁸ ÷ 2000 = 5.0 × 10⁴ V m⁻¹. (b) The field is far from uniform: near raindrops, pointed objects and the tip of the developing discharge it is much stronger, so the air ionises step by step. (c) W = QV = 20 × 1.0 × 10⁸ = 2.0 × 10⁹ J',
  ['C1: E = V/d', 'B1: local field much higher than average', 'C1: W = QV', 'C1: substitution'], sig=2, aq='W')
N('H', 6, 'An electron leaves the positive plate of a pair of parallel plates with a speed of 4.0 × 10⁶ m s⁻¹, moving straight towards the negative plate. The plates are 2.0 cm apart with 30 V between them. (a) Calculate the initial kinetic energy of the electron. (b) Calculate the work it must do against the field to reach the negative plate. (c) State whether it reaches the negative plate and calculate its speed there. Give only the speed from (c).' + take('e', 'me'), sqrt(2 * (0.5 * ME * 4.0e6 ** 2 - QE * 30) / ME), 'm s⁻¹',
  f'(a) E_k = ½ × 9.11 × 10⁻³¹ × (4.0 × 10⁶)² = {sf(0.5 * ME * 1.6e13)} J. (b) W = eV = 1.60 × 10⁻¹⁹ × 30 = 4.8 × 10⁻¹⁸ J. (c) E_k is larger than W, so it arrives with E_k = {sf(0.5 * ME * 1.6e13, 4)} − 4.8 × 10⁻¹⁸ = {sf(0.5 * ME * 1.6e13 - 4.8e-18)} J. v = √(2 × {sf(0.5 * ME * 1.6e13 - 4.8e-18, 4)} ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * (0.5 * ME * 1.6e13 - 4.8e-18) / ME))} m s⁻¹',
  ['C1: ½mv²', 'C1: W = eV', 'B1: compares energies, reaches plate', 'C1: KE remaining', 'C1: speed from KE'], aq='v')
N('H', 6, 'A small charged sphere hangs between two vertical parallel plates 5.0 cm apart. The horizontal force on it is measured for different p.d.s: V/V = 1000, 2000, 3000, 4000 and F/mN = 0.85, 1.70, 2.55, 3.40. (a) Describe the relationship between F and V. (b) Calculate the gradient of the graph of F against V. (c) Use the gradient to calculate the charge on the sphere, in nC. (d) Suggest why the sphere should be kept near the middle of the plates. Give only the answer to (c).', 0.85e-3 / 1000 * 0.050 * 1e9, 'nC',
  f'(a) F is proportional to V: a straight line through the origin. (b) Gradient = (3.40 − 0.85) × 10⁻³ ÷ (4000 − 1000) = {sf(2.55e-3 / 3000)} N V⁻¹. (c) F = QV/d, so gradient = Q/d and Q = {sf(2.55e-3 / 3000, 4)} × 0.050 = {sf(2.55e-3 / 3000 * 0.05)} C. In nC: {sf(2.55e-3 / 3000 * 0.05, 4)} × 10⁹ = {sf(2.55e-3 / 3000 * 0.05 * 1e9)}. (d) The field is uniform only away from the edges; near a plate the sphere also induces charge on it.',
  ['B1: F ∝ V', 'C1: gradient', 'M1: gradient = Q/d', 'C1: conversion to nC', 'B1: uniform field in centre'], aq='Q')
N('H', 6, 'Protons are released from rest at the positive plate of a pair of parallel plates 8.0 mm apart, with a p.d. of 2.0 kV between them. (a) Calculate the acceleration of a proton. (b) Calculate the time it takes to cross the gap, in ns. (c) Calculate its speed at the negative plate, and check it using energy. Give only the answer to (b).' + take('e', 'mp'), sqrt(2 * 8.0e-3 / (QE * 2000 / (MP * 8.0e-3))) * 1e9, 'ns',
  f'(a) a = eV/(md) = 1.60 × 10⁻¹⁹ × 2000 ÷ (1.67 × 10⁻²⁷ × 8.0 × 10⁻³) = {sf(QE * 2000 / (MP * 8e-3))} m s⁻². (b) t = √(2d/a) = √(2 × 8.0 × 10⁻³ ÷ {sf(QE * 2000 / (MP * 8e-3), 4)}) = {sf(sqrt(1.6e-2 / (QE * 2000 / (MP * 8e-3))))} s. In ns: {sf(sqrt(1.6e-2 / (QE * 2000 / (MP * 8e-3))), 4)} × 10⁹ = {sf(sqrt(1.6e-2 / (QE * 2000 / (MP * 8e-3))) * 1e9)}. (c) v = at = {sf(QE * 2000 / (MP * 8e-3), 4)} × {sf(sqrt(1.6e-2 / (QE * 2000 / (MP * 8e-3))), 4)} = {sf(sqrt(2 * QE * 2000 / MP))} m s⁻¹; energy gives √(2 × 1.60 × 10⁻¹⁹ × 2000 ÷ 1.67 × 10⁻²⁷) = {sf(sqrt(2 * QE * 2000 / MP))} m s⁻¹, the same.',
  ['C1: E = V/d and a = eE/m', 'C1: t = √(2d/a)', 'C1: conversion to ns', 'C1: v = at', 'B1: energy check agrees'], aq='t')
N('H', 6, 'In an electrostatic air cleaner, air flows at 2.0 m s⁻¹ between two parallel plates that are 30 cm long and 2.0 cm apart, with 8.0 kV between them. A dust particle of mass 1.0 × 10⁻¹⁵ kg carries a charge of 1.6 × 10⁻¹⁷ C and enters halfway between the plates. (a) Calculate the field strength. (b) Ignoring air resistance and gravity, calculate the acceleration of the particle across the gap. (c) Calculate how far the particle travels along the plates before it reaches one of them, in mm. Give only the answer to (c).',
  2.0 * sqrt(2 * 0.010 / (1.6e-17 * 8.0e3 / 0.020 / 1.0e-15)) * 1000, 'mm',
  f'(a) E = 8.0 × 10³ ÷ 0.020 = 4.0 × 10⁵ V m⁻¹. (b) a = QE/m = 1.6 × 10⁻¹⁷ × 4.0 × 10⁵ ÷ 1.0 × 10⁻¹⁵ = 6400 m s⁻². (c) It must move 1.0 cm sideways: t = √(2 × 0.010 ÷ 6400) = {sf(sqrt(0.02 / 6400))} s. Distance along = 2.0 × {sf(sqrt(0.02 / 6400), 4)} = {sf(2 * sqrt(0.02 / 6400))} m. In mm: {sf(2 * sqrt(0.02 / 6400), 4)} × 1000 = {sf(2 * sqrt(0.02 / 6400) * 1000)}',
  ['C1: E = V/d', 'C1: a = QE/m', 'M1: sideways distance 1.0 cm from rest', 'C1: t from s = ½at²', 'C1: distance = air speed × t'], aq='x')
N('H', 5, 'Two parallel plates 12 cm apart are at 0 V and +600 V. (a) Calculate the field strength. (b) Calculate the potential at a point 4.0 cm from the 0 V plate. (c) An electron moves from the point 4.0 cm from the 0 V plate to a point 10.0 cm from it. Calculate the work done on the electron by the field, in units of 10⁻¹⁷ J. Give only the answer to (c).' + take('e'), QE * (500 - 200), '10⁻¹⁷ J',
  f'(a) E = 600 ÷ 0.12 = 5000 V m⁻¹. (b) V = 5000 × 0.040 = 200 V. (c) At 10.0 cm, V = 5000 × 0.100 = 500 V. The electron moves towards higher potential, so the field does positive work: W = eΔV = 1.60 × 10⁻¹⁹ × (500 − 200) = {sf(QE * 300)} J',
  ['C1: E = V/d', 'C1: V = Ex', 'M1: W = QΔV', 'B1: positive work for electron moving to higher V'], aq='W')
N('H', 6, '(a) An electron accelerated through a p.d. V_a enters, midway and parallel, between deflecting plates of length L and separation d with p.d. V_p. Show that its deflection on leaving the plates is y = V_p L² ÷ (4V_a d). (b) For L = 3.0 cm, d = 0.80 cm and V_a = 2000 V, calculate the deflecting p.d. needed to give y = 2.0 mm. Give only the answer to (b).', 4 * 2000 * 0.0080 * 0.0020 / 0.030 ** 2, 'V',
  f'(a) ½mv² = eV_a gives v² = 2eV_a/m. t = L/v and a = eV_p/(md). y = ½at² = ½ × (eV_p/md) × L²m/(2eV_a) = V_p L²/(4V_a d). (b) V_p = 4V_a dy/L² = 4 × 2000 × 0.0080 × 0.0020 ÷ 0.030² = {sf(4 * 2000 * 0.008 * 0.002 / 0.0009)} V',
  ['C1: v² = 2eV_a/m', 'C1: t = L/v and a = eV_p/(md)', 'M1: substitution into y = ½at²', 'B1: result shown', 'C1: rearranged for V_p'], aq='V_p')
N('H', 6, 'An ion thruster on a spacecraft accelerates singly charged xenon ions (mass 2.18 × 10⁻²⁵ kg) from rest through 1.2 kV between two grids 1.0 mm apart. (a) Calculate the field strength between the grids. (b) Calculate the exit speed of the ions. (c) The thruster emits 3.0 × 10¹⁸ ions per second. Calculate the thrust, in mN. Give only the answer to (c).' + take('e'), 3.0e18 * 2.18e-25 * sqrt(2 * QE * 1200 / 2.18e-25) * 1000, 'mN',
  f'(a) E = 1200 ÷ 1.0 × 10⁻³ = 1.2 × 10⁶ V m⁻¹. (b) v = √(2 × 1.60 × 10⁻¹⁹ × 1200 ÷ 2.18 × 10⁻²⁵) = {sf(sqrt(2 * QE * 1200 / 2.18e-25))} m s⁻¹. (c) Thrust = rate of change of momentum = 3.0 × 10¹⁸ × 2.18 × 10⁻²⁵ × {sf(sqrt(2 * QE * 1200 / 2.18e-25), 4)} = {sf(3e18 * 2.18e-25 * sqrt(2 * QE * 1200 / 2.18e-25))} N. In mN: {sf(3e18 * 2.18e-25 * sqrt(2 * QE * 1200 / 2.18e-25), 4)} × 1000 = {sf(3e18 * 2.18e-25 * sqrt(2 * QE * 1200 / 2.18e-25) * 1000)}',
  ['C1: E = V/d', 'C1: ½mv² = eV', 'M1: F = (number per second) × mv', 'C1: substitution', 'C1: conversion to mN'], aq='F')

# ═════════════════════════ 21.4 Force on a charge (16/16/12) ═════════════════════════
lesson('21.4')
N('E', 2, 'A charged dust particle carrying −2.0 nC is in an electric field of strength 3.0 × 10⁴ N C⁻¹. Calculate the magnitude of the force on it.', 2.0e-9 * 3.0e4, 'N',
  'F = EQ = 3.0 × 10⁴ × 2.0 × 10⁻⁹ = 6.0 × 10⁻⁵ N', ['C1: F = EQ with Q in C'], sig=2, aq='F')
M('E', 1, 'In which direction is the electric force on a positive charge in an electric field?', 'In the direction of the field', ['Opposite to the field', 'At right angles to the field', 'Towards the nearest earthed object'], 'The field direction is defined as the direction of the force on a positive charge.')
M('E', 1, 'An electron and a proton are placed at the same point in an electric field. How do the forces on them compare?', 'Equal in size and opposite in direction', ['Equal in size and in the same direction', 'The force on the proton is 1840 times larger', 'The force on the electron is 1840 times larger'], 'F = QE and the charges are equal in size but opposite in sign.')
N('E', 2, 'An α-particle has a charge of +2e. Calculate the force on it in an electric field of 5.0 × 10⁴ N C⁻¹, in units of 10⁻¹⁴ N.' + take('e'), 2 * QE * 5.0e4, '10⁻¹⁴ N',
  f'F = 2eE = 2 × 1.60 × 10⁻¹⁹ × 5.0 × 10⁴ = {sf(2 * QE * 5e4)} N', ['C1: Q = 2e and F = QE'], sig=2, aq='F')
N('E', 2, 'What charge, in µC, would experience a force of 1.0 N in an electric field of 2.0 × 10⁵ N C⁻¹?', 1.0 / 2.0e5 * 1e6, 'µC',
  'Q = F/E = 1.0 ÷ 2.0 × 10⁵ = 5.0 × 10⁻⁶ C. In µC: 5.0 × 10⁻⁶ × 10⁶ = 5.0', ['C1: Q = F/E'], sig=2, aq='Q')
M('E', 1, 'A charged particle is moved from one point to another inside a uniform electric field. What happens to the electric force on it?', 'It stays the same in size and direction', ['It increases as the particle moves along the field', 'It decreases as the particle moves along the field', 'It changes direction'], 'A uniform field has the same E everywhere, so F = QE is constant.')
N('E', 2, 'A singly charged ion (charge +e) experiences a force of 8.0 × 10⁻¹⁵ N. Calculate the electric field strength.' + take('e'), 8.0e-15 / QE, 'N C⁻¹',
  'E = F/Q = 8.0 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁹ = 5.0 × 10⁴ N C⁻¹', ['C1: E = F/e'], sig=2, aq='E')
M('E', 1, 'A charged particle in a uniform field has its charge doubled while its mass stays the same. What happens to its acceleration?', 'It doubles', ['It halves', 'It stays the same', 'It quadruples'], 'a = F/m = QE/m, so with E and m fixed the acceleration is proportional to Q.')
N('E', 2, 'A polystyrene ball carrying 4.0 µC hangs between two plates and is pushed sideways by an electric force of 0.012 N. What is the electric field strength at the ball?', 0.012 / 4.0e-6, 'N C⁻¹',
  'E = F/Q = 0.012 ÷ 4.0 × 10⁻⁶ = 3000 N C⁻¹', ['C1: E = F/Q'], sig=2, aq='E')
M('E', 1, 'A charge moves at right angles to a uniform electric field. How much work does the electric force do on it during this movement?', 'None', ['QE times the distance moved', 'QE divided by the distance', 'It depends on the speed of the charge'], 'Work = force × displacement in the direction of the force; here the displacement is perpendicular to F.')
N('E', 2, 'Calculate the force on an electron in an electric field of 2.0 × 10⁵ N C⁻¹, in units of 10⁻¹⁴ N.' + take('e'), QE * 2.0e5, '10⁻¹⁴ N',
  f'F = eE = 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = {sf(QE * 2e5)} N', ['C1: F = eE'], sig=2, aq='F')
M('E', 1, 'An electron is released from rest in a uniform electric field. How does it move?', 'In the opposite direction to the field, with increasing speed', ['In the direction of the field, with increasing speed', 'In the opposite direction to the field, at constant speed', 'In a circle'], 'The force on a negative charge is opposite to E and constant, so it accelerates uniformly.')
N('E', 1, 'A charged particle in a uniform field feels a force of 6.0 µN. The field strength is halved. What is the new force, in µN?', 3.0, 'µN',
  'F = QE, so halving E halves F: 6.0 ÷ 2 = 3.0 µN', [], sig=2, aq='F')
M('E', 1, 'An electron, a proton and an α-particle are placed in the same uniform electric field. Which has the largest acceleration?', 'The electron', ['The proton', 'The α-particle', 'They all have the same acceleration'], 'a = QE/m: the electron\'s tiny mass gives by far the largest charge-to-mass ratio.')
N('E', 2, 'A small particle experiences a force of 4.8 × 10⁻¹⁴ N in a field of 1.0 × 10⁵ N C⁻¹. How many electronic charges does it carry?' + take('e'), 4.8e-14 / 1.0e5 / QE, None,
  'Q = F/E = 4.8 × 10⁻¹⁴ ÷ 1.0 × 10⁵ = 4.8 × 10⁻¹⁹ C. Number = 4.8 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 3.0', ['C1: Q = F/E then ÷ e'], sig=2, aq='n')
M('E', 1, 'A negative charge in an electric field experiences an upward force. In which direction is the field?', 'Downwards', ['Upwards', 'Horizontally', 'There is not enough information'], 'The force on a negative charge is opposite to the field.')
# medium
N('M', 3, 'An oil drop of mass 1.6 × 10⁻¹⁵ kg is held stationary in an upward electric field of 4.9 × 10⁴ N C⁻¹. Calculate the charge on the drop, in units of 10⁻¹⁹ C.' + take('g'), 1.6e-15 * g / 4.9e4, '10⁻¹⁹ C',
  f'Electric force balances weight: QE = mg, so Q = 1.6 × 10⁻¹⁵ × 9.81 ÷ 4.9 × 10⁴ = {sf(1.6e-15 * 9.81 / 4.9e4)} C', ['M1: QE = mg', 'C1: substitution'], aq='Q')
N('M', 3, 'Calculate the acceleration of an electron in a uniform electric field of 3.0 × 10³ N C⁻¹.' + take('e', 'me'), QE * 3.0e3 / ME, 'm s⁻²',
  f'a = eE/m = 1.60 × 10⁻¹⁹ × 3.0 × 10³ ÷ 9.11 × 10⁻³¹ = {sf(QE * 3e3 / ME)} m s⁻²', ['C1: F = eE', 'C1: a = F/m'], aq='a')
N('M', 4, 'A proton starts from rest in a uniform electric field of 1.0 × 10⁴ N C⁻¹ and travels 5.0 cm along the field. Calculate its final speed.' + take('e', 'mp'), sqrt(2 * QE * 1.0e4 / MP * 0.050), 'm s⁻¹',
  f'a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10⁴ ÷ 1.67 × 10⁻²⁷ = {sf(QE * 1e4 / MP)} m s⁻². v² = 2as, so v = √(2 × {sf(QE * 1e4 / MP, 4)} × 0.050) = {sf(sqrt(2 * QE * 1e4 / MP * 0.05))} m s⁻¹',
  ['C1: a = eE/m', 'M1: v² = u² + 2as with u = 0', 'C1: substitution'], aq='v')
M('M', 3, 'An electron is moving in the same direction as a uniform electric field. What happens to its speed?', 'It decreases, because the force on it is opposite to its motion', ['It increases, because the force is in its direction of motion', 'It stays constant, because the field is uniform', 'It increases and then becomes constant'], 'The force on an electron is opposite to E, so moving along E it decelerates.', ['C1: force opposite to E for electron', 'C1: decelerates'])
N('M', 3, 'A proton is in a uniform electric field of 500 N C⁻¹ near the Earth\'s surface. Calculate the ratio of the electric force on it to its weight.' + take('e', 'mp', 'g'), QE * 500 / (MP * g), None,
  f'F = eE = 1.60 × 10⁻¹⁹ × 500 = {sf(QE * 500)} N. W = mg = 1.67 × 10⁻²⁷ × 9.81 = {sf(MP * 9.81)} N. Ratio = {sf(QE * 500, 4)} ÷ {sf(MP * 9.81, 4)} = {sf(QE * 500 / (MP * 9.81))}', ['C1: F = eE and W = mg', 'C1: ratio'], aq='ratio')
N('M', 4, 'An electron moving at 5.0 × 10⁶ m s⁻¹ enters a region where there is a uniform field of 2.0 × 10³ N C⁻¹ in the same direction as its velocity. Calculate how far it travels before it stops, in cm.' + take('e', 'me'), (5.0e6) ** 2 / (2 * QE * 2.0e3 / ME) * 100, 'cm',
  f'The force is opposite to its motion: deceleration a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10³ ÷ 9.11 × 10⁻³¹ = {sf(QE * 2e3 / ME)} m s⁻². s = u²/2a = (5.0 × 10⁶)² ÷ (2 × {sf(QE * 2e3 / ME, 4)}) = {sf(2.5e13 / (2 * QE * 2e3 / ME))} m. In cm: {sf(2.5e13 / (2 * QE * 2e3 / ME), 4)} × 100 = {sf(2.5e13 / (2 * QE * 2e3 / ME) * 100)}',
  ['B1: force opposite to motion', 'C1: a = eE/m', 'C1: 0 = u² − 2as'], aq='s')
M('M', 3, 'A charged particle is projected at right angles to a uniform electric field. Which quantity stays constant while it is in the field?', 'Its velocity component at right angles to the field', ['Its speed', 'Its velocity component along the field', 'Its kinetic energy'], 'There is no force perpendicular to E, so that component is unchanged; the component along E changes uniformly.', ['C1: force only along E', 'C1: perpendicular component unchanged'])
N('M', 3, 'In an ink-jet printer, an ink drop of mass 2.0 × 10⁻¹⁰ kg carries a charge of 4.0 × 10⁻¹³ C and passes between deflecting plates where the field is 8.0 × 10⁵ N C⁻¹. Calculate the acceleration of the drop due to the field.', 4.0e-13 * 8.0e5 / 2.0e-10, 'm s⁻²',
  'a = QE/m = 4.0 × 10⁻¹³ × 8.0 × 10⁵ ÷ 2.0 × 10⁻¹⁰ = 1600 m s⁻²', ['C1: F = QE', 'C1: a = F/m'], sig=2, aq='a')
N('M', 3, 'A singly charged lithium ion (mass 1.15 × 10⁻²⁶ kg) is in a uniform field of 4.0 × 10⁴ N C⁻¹. Calculate its acceleration.' + take('e'), QE * 4.0e4 / 1.15e-26, 'm s⁻²',
  f'a = eE/m = 1.60 × 10⁻¹⁹ × 4.0 × 10⁴ ÷ 1.15 × 10⁻²⁶ = {sf(QE * 4e4 / 1.15e-26)} m s⁻²', ['C1: F = eE', 'C1: a = F/m'], aq='a')
M('M', 4, 'An oil drop carrying a negative charge is held stationary between two horizontal plates. It suddenly picks up one more electron. What happens next, with the p.d. unchanged?', 'It accelerates upwards, because the upward electric force is now larger than its weight', ['It falls, because its weight has increased', 'It stays still, because one electron makes no difference', 'It moves sideways towards a plate edge'], 'The charge magnitude increases, so QE exceeds mg; the electron\'s extra mass is negligible.', ['C1: QE increases', 'C1: extra mass negligible', 'C1: net upward force'])
N('M', 3, 'An electron moves 3.0 cm in the direction opposite to a uniform field of 2.0 × 10⁴ N C⁻¹. Calculate the work done on it by the electric force, in units of 10⁻¹⁷ J.' + take('e'), QE * 2.0e4 * 0.030, '10⁻¹⁷ J',
  f'The force on the electron is opposite to E, in its direction of motion, so the work is positive: W = eEd = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ × 0.030 = {sf(QE * 2e4 * 0.03)} J', ['C1: F = eE', 'C1: W = Fd'], aq='W')
N('M', 3, 'A proton starts from rest in a field of 2.0 × 10³ N C⁻¹. Calculate the time it takes to reach a speed of 1.0 × 10⁵ m s⁻¹, in µs.' + take('e', 'mp'), 1.0e5 / (QE * 2.0e3 / MP) * 1e6, 'µs',
  f'a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10³ ÷ 1.67 × 10⁻²⁷ = {sf(QE * 2e3 / MP)} m s⁻². t = v/a = 1.0 × 10⁵ ÷ {sf(QE * 2e3 / MP, 4)} = {sf(1e5 / (QE * 2e3 / MP))} s. In µs: {sf(1e5 / (QE * 2e3 / MP), 4)} × 10⁶ = {sf(1e5 / (QE * 2e3 / MP) * 1e6)}', ['C1: a = eE/m', 'C1: t = v/a'], aq='t')
M('M', 3, 'An electron and a proton are in the same uniform field. Which row is correct?', 'Forces equal in size; the electron\'s acceleration is about 1840 times larger', ['The proton\'s force is 1840 times larger; equal accelerations', 'Forces equal in size; equal accelerations', 'The electron\'s force is 1840 times larger; the electron\'s acceleration is 1840 times larger'], 'F = eE for both; a = F/m, and mₚ/mₑ ≈ 1840.', ['C1: equal forces', 'C1: a ∝ 1/m'])
N('M', 4, 'A small sphere of mass 2.0 × 10⁻⁴ kg carrying a charge of 15 nC hangs on a thread between two vertical parallel plates 6.0 cm apart with a p.d. of 3.0 kV. Calculate the angle the thread makes with the vertical.' + take('g'), degrees(atan(15e-9 * 3.0e3 / 0.060 / (2.0e-4 * g))), '°',
  f'E = 3.0 × 10³ ÷ 0.060 = 5.0 × 10⁴ V m⁻¹. F = QE = 15 × 10⁻⁹ × 5.0 × 10⁴ = 7.5 × 10⁻⁴ N. tan θ = F/mg = 7.5 × 10⁻⁴ ÷ (2.0 × 10⁻⁴ × 9.81) = {sf(7.5e-4 / (2e-4 * 9.81), 4)}, so θ = tan⁻¹ {sf(7.5e-4 / (2e-4 * 9.81), 4)} = {sf(degrees(atan(7.5e-4 / (2e-4 * 9.81))))}°',
  ['C1: E = V/d', 'C1: F = QE', 'M1: tan θ = F/mg'], aq='θ')
N('M', 3, 'A dust particle of mass 5.0 × 10⁻¹³ kg carries a charge of 8.0 × 10⁻¹⁵ C. Calculate the vertical electric field strength needed to stop it falling.' + take('g'), 5.0e-13 * g / 8.0e-15, 'N C⁻¹',
  f'QE = mg, so E = 5.0 × 10⁻¹³ × 9.81 ÷ 8.0 × 10⁻¹⁵ = {sf(5e-13 * 9.81 / 8e-15)} N C⁻¹', ['M1: QE = mg', 'C1: substitution'], aq='E')
M('M', 3, 'A positive ion and an electron are released together from the midpoint between two charged parallel plates. Which statement is correct?', 'They move in opposite directions, and the electron reaches its plate first', ['They move in the same direction at the same rate', 'They move in opposite directions and arrive at the same time', 'The ion reaches its plate first because it is heavier'], 'Equal and opposite forces; the electron\'s far larger acceleration means a shorter time to cover the same distance.', ['C1: opposite forces', 'C1: larger a for electron'])
# hard
N('H', 6, 'An oil drop of radius 1.2 µm and density 900 kg m⁻³ is held stationary between two horizontal plates 8.0 mm apart when the p.d. between them is 1065 V. (a) Calculate the mass of the drop. (b) Calculate the charge on the drop, in units of 10⁻¹⁹ C. (c) State the number of excess electrons on the drop. Give only the answer to (b).' + take('g'), 900 * 4 / 3 * pi * (1.2e-6) ** 3 * g * 8.0e-3 / 1065, '10⁻¹⁹ C',
  f'(a) m = ρ × (4/3)πr³ = 900 × 4/3 × π × (1.2 × 10⁻⁶)³ = {sf(900 * 4 / 3 * pi * 1.2e-6 ** 3)} kg. (b) QV/d = mg, so Q = mgd/V = {sf(900 * 4 / 3 * pi * 1.2e-6 ** 3, 4)} × 9.81 × 8.0 × 10⁻³ ÷ 1065 = {sf(900 * 4 / 3 * pi * 1.2e-6 ** 3 * 9.81 * 8e-3 / 1065)} C. (c) {sf(900 * 4 / 3 * pi * 1.2e-6 ** 3 * 9.81 * 8e-3 / 1065, 4)} ÷ 1.60 × 10⁻¹⁹ = {sf(900 * 4 / 3 * pi * 1.2e-6 ** 3 * 9.81 * 8e-3 / 1065 / QE)}, so 3 electrons.',
  ['C1: m = ρ(4/3)πr³', 'M1: QE = mg with E = V/d', 'C1: substitution', 'C1: Q value', 'B1: 3 electrons'], aq='Q')
N('H', 6, 'An electron moving at 3.0 × 10⁷ m s⁻¹ enters a uniform field of 2.0 × 10⁴ N C⁻¹ at right angles to the field. The field region is 6.0 cm long. (a) Calculate the time the electron spends in the field. (b) Calculate the velocity component it gains along the field direction. (c) Calculate the angle between its velocity and its original direction as it leaves the field. Give only the answer to (c).' + take('e', 'me'), degrees(atan(QE * 2.0e4 / ME * (0.060 / 3.0e7) / 3.0e7)), '°',
  f'(a) t = 0.060 ÷ 3.0 × 10⁷ = 2.0 × 10⁻⁹ s. (b) a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ ÷ 9.11 × 10⁻³¹ = {sf(QE * 2e4 / ME)} m s⁻²; v_y = at = {sf(QE * 2e4 / ME, 4)} × 2.0 × 10⁻⁹ = {sf(QE * 2e4 / ME * 2e-9)} m s⁻¹. (c) tan θ = {sf(QE * 2e4 / ME * 2e-9, 4)} ÷ 3.0 × 10⁷ = {sf(QE * 2e4 / ME * 2e-9 / 3e7, 4)}, so θ = tan⁻¹ {sf(QE * 2e4 / ME * 2e-9 / 3e7, 4)} = {sf(degrees(atan(QE * 2e4 / ME * 2e-9 / 3e7)))}°',
  ['C1: t = L/v', 'C1: a = eE/m', 'C1: v_y = at', 'M1: tan θ = v_y/v_x', 'C1: angle'], aq='θ')
N('H', 5, 'A proton and an electron enter the same uniform electric field with the same speed, moving at right angles to the field, and travel the same distance through it. (a) Explain why both spend the same time in the field. (b) Compare the forces on them. (c) Calculate the ratio (sideways deflection of proton) ÷ (sideways deflection of electron). Give only the answer to (c).' + take('me', 'mp'), ME / MP, None,
  f'(a) Their velocity components perpendicular to the field are equal and unchanged, so t = L/v is the same. (b) Equal in magnitude, eE, but in opposite directions. (c) y = ½at² with a = eE/m, so y ∝ 1/m: ratio = 9.11 × 10⁻³¹ ÷ 1.67 × 10⁻²⁷ = {sf(ME / MP)}, and the deflections are in opposite directions.',
  ['B1: same time, constant perpendicular velocity', 'B1: equal and opposite forces', 'M1: y ∝ a ∝ 1/m', 'C1: mass ratio'], aq='ratio')
N('H', 6, 'An oil drop of mass 4.0 × 10⁻¹⁵ kg carrying a charge of 6.4 × 10⁻¹⁹ C is between horizontal plates where there is an upward field of 8.0 × 10⁴ N C⁻¹. (a) Calculate the electric force on the drop. (b) Calculate its weight. (c) Ignoring air resistance, calculate the drop\'s acceleration. (d) Explain why, in practice, the drop soon moves at a constant speed. Give only the answer to (c).' + take('g'), (6.4e-19 * 8.0e4 - 4.0e-15 * g) / 4.0e-15, 'm s⁻²',
  f'(a) F = QE = 6.4 × 10⁻¹⁹ × 8.0 × 10⁴ = {sf(6.4e-19 * 8e4)} N upwards. (b) W = 4.0 × 10⁻¹⁵ × 9.81 = {sf(4e-15 * 9.81)} N. (c) a = (F − W)/m = ({sf(6.4e-19 * 8e4, 4)} − {sf(4e-15 * 9.81, 4)}) ÷ 4.0 × 10⁻¹⁵ = {sf((6.4e-19 * 8e4 - 4e-15 * 9.81) / 4e-15)} m s⁻², upwards. (d) Air resistance increases with speed until it balances the resultant force, so the drop reaches a terminal velocity.',
  ['C1: F = QE', 'C1: W = mg', 'M1: resultant force = F − W', 'C1: a = F_net/m', 'B1: drag rises to give terminal velocity'], aq='a')
N('H', 5, 'A proton moving at 2.0 × 10⁵ m s⁻¹ enters a region where a uniform field of 1.5 × 10³ N C⁻¹ points opposite to its velocity. (a) Calculate its deceleration. (b) Calculate the time taken for it to stop. (c) Calculate the distance it travels before stopping. (d) Describe its motion after it stops. Give only the answer to (c).' + take('e', 'mp'), (2.0e5) ** 2 / (2 * QE * 1.5e3 / MP), 'm',
  f'(a) a = eE/m = 1.60 × 10⁻¹⁹ × 1.5 × 10³ ÷ 1.67 × 10⁻²⁷ = {sf(QE * 1.5e3 / MP)} m s⁻². (b) t = u/a = 2.0 × 10⁵ ÷ {sf(QE * 1.5e3 / MP, 4)} = {sf(2e5 / (QE * 1.5e3 / MP))} s. (c) s = u²/2a = (2.0 × 10⁵)² ÷ (2 × {sf(QE * 1.5e3 / MP, 4)}) = {sf(4e10 / (2 * QE * 1.5e3 / MP))} m. (d) The force still acts along the field, so it accelerates back the way it came and leaves the region with its original speed.',
  ['C1: a = eE/m', 'C1: t = u/a', 'M1: s = u²/2a', 'B1: returns with same speed'], aq='s')
N('H', 6, 'A ball of mass 0.010 kg carrying +2.0 µC is released from rest in a uniform horizontal electric field of 5.0 × 10⁴ N C⁻¹. (a) Calculate the horizontal electric force on the ball. (b) Calculate the resultant force on the ball. (c) Calculate the angle between the ball\'s path and the vertical, and explain why the path is a straight line. Give only the angle from (c).' + take('g'), degrees(atan(2.0e-6 * 5.0e4 / (0.010 * g))), '°',
  f'(a) F = QE = 2.0 × 10⁻⁶ × 5.0 × 10⁴ = 0.10 N. (b) Weight = 0.010 × 9.81 = 0.0981 N; resultant = √(0.10² + 0.0981²) = {sf(sqrt(0.01 + 0.0981 ** 2))} N. (c) tan θ = 0.10 ÷ 0.0981 = {sf(0.1 / 0.0981, 4)}, so θ = tan⁻¹ {sf(0.1 / 0.0981, 4)} = {sf(degrees(atan(0.1 / 0.0981)))}°. Starting from rest with a constant resultant force, the ball accelerates along the line of that force.',
  ['C1: F = QE', 'C1: weight', 'C1: resultant by Pythagoras', 'M1: tan θ = F_E/W', 'B1: constant force from rest gives straight line'], aq='θ')
N('H', 6, 'A mineral separator lets a mixture of charged particles fall from rest between two vertical plates that produce a horizontal field of 5.0 × 10⁵ N C⁻¹. One type of particle has a charge-to-mass ratio of 2.0 × 10⁻⁶ C kg⁻¹. The particles fall 1.0 m before leaving the plates. (a) Calculate the horizontal acceleration of this type of particle. (b) Calculate the time taken to fall 1.0 m. (c) Calculate its horizontal displacement when it leaves the plates, in cm. (d) Explain how this separates particles with charges of opposite sign. Give only the answer to (c).' + take('g'), 0.5 * 2.0e-6 * 5.0e5 * (2 * 1.0 / g) * 100, 'cm',
  f'(a) a = (Q/m)E = 2.0 × 10⁻⁶ × 5.0 × 10⁵ = 1.0 m s⁻². (b) t = √(2 × 1.0 ÷ 9.81) = {sf(sqrt(2 / 9.81))} s. (c) x = ½at² = 0.5 × 1.0 × {sf(sqrt(2 / 9.81), 4)}² = {sf(0.5 * 2 / 9.81)} m. In cm: {sf(0.5 * 2 / 9.81, 4)} × 100 = {sf(0.5 * 2 / 9.81 * 100)}. (d) Positive particles are pushed one way along the field and negative ones the other, so they land in different collecting bins.',
  ['C1: a = (Q/m)E', 'C1: vertical motion: t from s = ½gt²', 'M1: horizontal and vertical motions independent', 'C1: x = ½at²', 'B1: opposite charges deflected opposite ways'], aq='x')
N('H', 6, 'In an experiment, the acceleration of identical ions is measured in different uniform fields: E/10⁴ N C⁻¹ = 1.0, 2.0, 3.0, 4.0 and a/10¹² m s⁻² = 0.96, 1.92, 2.88, 3.84. (a) Show that a is proportional to E. (b) Calculate the gradient of the graph of a against E and state what it represents. (c) Each ion carries charge +e. Calculate the mass of an ion, in units of 10⁻²⁷ kg, and identify the ion. Give only the mass from (c).' + take('e'), QE / (0.96e12 / 1.0e4), '10⁻²⁷ kg',
  f'(a) a/E = 0.96 × 10¹² ÷ 1.0 × 10⁴ = 9.6 × 10⁷ for every reading, so a ∝ E. (b) Gradient = (3.84 − 0.96) × 10¹² ÷ ((4.0 − 1.0) × 10⁴) = 9.6 × 10⁷ C kg⁻¹, which is Q/m since a = (Q/m)E. (c) m = e ÷ gradient = 1.60 × 10⁻¹⁹ ÷ 9.6 × 10⁷ = {sf(QE / 9.6e7)} kg: a proton (hydrogen ion).',
  ['B1: a/E constant', 'C1: gradient', 'M1: gradient = Q/m', 'C1: m = e/gradient', 'B1: identifies proton'], aq='m')
N('H', 5, 'An electron starts from rest and is accelerated through a distance of 4.0 cm by a uniform field of 2.5 × 10⁴ N C⁻¹. (a) Calculate the work done on the electron by the field. (b) Express its kinetic energy in electronvolts. (c) Calculate its final speed. Give only the answer to (c).' + take('e', 'me'), sqrt(2 * QE * 2.5e4 * 0.040 / ME), 'm s⁻¹',
  f'(a) W = eEd = 1.60 × 10⁻¹⁹ × 2.5 × 10⁴ × 0.040 = {sf(QE * 2.5e4 * 0.04)} J. (b) The p.d. crossed is Ed = 2.5 × 10⁴ × 0.040 = 1000 V, so E_k = 1000 eV. (c) v = √(2W/m) = √(2 × {sf(QE * 2.5e4 * 0.04)} ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 2.5e4 * 0.04 / ME))} m s⁻¹',
  ['C1: W = Fd = eEd', 'C1: E_k in eV', 'M1: W = ½mv²', 'C1: substitution'], aq='v')
N('H', 6, 'A simple pendulum has a bob of mass 0.050 kg carrying a charge of +5.0 µC on a string 0.80 m long. It swings in a uniform downward electric field of 4.0 × 10⁴ N C⁻¹. (a) Calculate the electric force on the bob. (b) Calculate the effective gravitational field strength acting on the bob. (c) Calculate the period of small oscillations. (d) State how the period would change if the charge were negative. Give only the answer to (c).' + take('g'), 2 * pi * sqrt(0.80 / (g + 5.0e-6 * 4.0e4 / 0.050)), 's',
  f'(a) F = QE = 5.0 × 10⁻⁶ × 4.0 × 10⁴ = 0.20 N, downwards. (b) g_eff = 9.81 + 0.20 ÷ 0.050 = 13.81 N kg⁻¹. (c) T = 2π√(l/g_eff) = 2π × √(0.80 ÷ 13.81) = {sf(2 * pi * sqrt(0.8 / 13.81))} s. (d) The electric force would act upwards, reducing g_eff to 5.81 N kg⁻¹, so the period would increase.',
  ['C1: F = QE', 'M1: g_eff = g + F/m', 'C1: T = 2π√(l/g)', 'C1: substitution', 'B1: period increases for negative charge'], aq='T')
N('H', 5, 'An oil drop carrying three excess electrons is held stationary between horizontal plates when the p.d. is 600 V. (a) Explain why a larger charge needs a smaller p.d. to hold the drop still. (b) The drop gains one more electron. Calculate the p.d. now needed to keep it stationary. (c) State what happens if the p.d. is left at 600 V. Give only the answer to (b).', 600 * 3 / 4, 'V',
  '(a) For balance QV/d = mg, so V = mgd/Q: with m and d fixed, V ∝ 1/Q. (b) V = 600 × 3 ÷ 4 = 450 V. (c) The electric force (4e × 600/d) is now larger than the weight, so the drop accelerates upwards.',
  ['M1: QV/d = mg', 'B1: V ∝ 1/Q', 'C1: substitution', 'B1: drop moves upwards'], sig=2, aq='V')
N('H', 7, 'Electrons accelerated from rest through 800 V enter, midway and parallel, between two horizontal plates 5.0 cm long and 2.0 cm apart with a p.d. of 100 V between them. A screen is 20 cm beyond the end of the plates. (a) Calculate the speed of the electrons. (b) Calculate the time spent between the plates and the vertical acceleration there. (c) Calculate the vertical deflection and vertical velocity on leaving the plates. (d) Calculate the total vertical deflection of the spot on the screen, in mm. Give only the answer to (d).' + take('e', 'me'),
  (0.5 * (QE * 5000 / ME) * (0.050 / sqrt(2 * QE * 800 / ME)) ** 2 + (QE * 5000 / ME) * (0.050 / sqrt(2 * QE * 800 / ME)) * (0.20 / sqrt(2 * QE * 800 / ME))) * 1000, 'mm',
  f'(a) v = √(2 × 1.60 × 10⁻¹⁹ × 800 ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 800 / ME))} m s⁻¹. (b) t = 0.050 ÷ {sf(sqrt(2 * QE * 800 / ME), 4)} = {sf(0.05 / sqrt(2 * QE * 800 / ME))} s. E = 100 ÷ 0.020 = 5000 V m⁻¹, so a = 1.60 × 10⁻¹⁹ × 5000 ÷ 9.11 × 10⁻³¹ = {sf(QE * 5000 / ME)} m s⁻². (c) y₁ = ½at² = 0.5 × {sf(QE * 5000 / ME, 4)} × ({sf(0.05 / sqrt(2 * QE * 800 / ME), 4)})² = {sf(0.5 * QE * 5000 / ME * (0.05 / sqrt(2 * QE * 800 / ME)) ** 2)} m. v_y = at = {sf(QE * 5000 / ME, 4)} × {sf(0.05 / sqrt(2 * QE * 800 / ME), 4)} = {sf(QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME))} m s⁻¹. (d) Beyond the plates it travels in a straight line for t₂ = 0.20 ÷ {sf(sqrt(2 * QE * 800 / ME), 4)} = {sf(0.2 / sqrt(2 * QE * 800 / ME))} s, rising a further {sf(QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME), 4)} × {sf(0.2 / sqrt(2 * QE * 800 / ME), 4)} = {sf(QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME) * 0.2 / sqrt(2 * QE * 800 / ME))} m. Total deflection = {sf(0.5 * QE * 5000 / ME * (0.05 / sqrt(2 * QE * 800 / ME)) ** 2, 4)} + {sf(QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME) * 0.2 / sqrt(2 * QE * 800 / ME), 4)} = {sf(0.5 * QE * 5000 / ME * (0.05 / sqrt(2 * QE * 800 / ME)) ** 2 + QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME) * 0.2 / sqrt(2 * QE * 800 / ME))} m. In mm: {sf(0.5 * QE * 5000 / ME * (0.05 / sqrt(2 * QE * 800 / ME)) ** 2 + QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME) * 0.2 / sqrt(2 * QE * 800 / ME), 4)} × 1000 = {sf((0.5 * QE * 5000 / ME * (0.05 / sqrt(2 * QE * 800 / ME)) ** 2 + QE * 5000 / ME * 0.05 / sqrt(2 * QE * 800 / ME) * 0.2 / sqrt(2 * QE * 800 / ME)) * 1000)}',
  ['C1: ½mv² = eV', 'C1: t = L/v and a = eE/m', 'C1: y₁ = ½at²', 'C1: v_y = at', 'M1: straight line beyond plates', 'C1: total deflection'], aq='y')
